(333232,37026,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До п''ятниці весь офіс ... відео з її балансом. Яка катастрофа!'::text,'побачить'::text,'побачить'::text,'дивитиметься'::text,'До п''ятниці весь офіс побачить відео з її балансом. Яка катастрофа!'::text),
