(345860,38429,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kaptan, buzdağının geçişini izlemek için güvertede ... önerdi.'::text,'kalmayı'::text,'kalmayı'::text,'kaldılar'::text,'Kaptan, buzdağının geçişini izlemek için güvertede kalmayı önerdi.'::text),
