(381918,42436,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, er ... diesen Koffer kilometerweit gerollt haben; angeblich sind die Rollen total abgenutzt.'::text,'muss'::text,'hätte'::text,'würde'::text,'Mädel, er muss diesen Koffer kilometerweit gerollt haben; angeblich sind die Rollen total abgenutzt.'::text),
(381922,42436,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він ... ту валізу кілометрами; кажуть, колеса вже стерті.'::text,'напевно, котив'::text,'мав би котити'::text,'котив би'::text,'Подруго, він напевно, котив ту валізу кілометрами; кажуть, колеса вже стерті.'::text),
(381921,42436,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, él ... rodado esa maleta durante kilómetros; al parecer las ruedas están destrozadas.'::text,'debe de haber'::text,'debería haber'::text,'habría'::text,'Amiga, él debe de haber rodado esa maleta durante kilómetros; al parecer las ruedas están destrozadas.'::text),
(381920,42436,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il ... cette valise sur des kilomètres ; apparemment les roues sont usées.'::text,'a dû faire rouler'::text,'aurait dû faire rouler'::text,'aurait fait rouler'::text,'Meuf, il a dû faire rouler cette valise sur des kilomètres ; apparemment les roues sont usées.'::text),
