(364010,40446,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La lanterne rouge ... près de la fenêtre pendant des heures avant que la lumière de la cuisine ne s''allume.'::text,'avait brillé'::text,'a brillé'::text,'brillait'::text,'La lanterne rouge avait brillé près de la fenêtre pendant des heures avant que la lumière de la cuisine ne s''allume.'::text),
(364013,40446,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mutfak ışığı yanmadan önce kırmızı fener saatlerce pencerenin yanında ...'::text,'parlıyordu'::text,'parlıyor'::text,'parlıyordu'::text,'Mutfak ışığı yanmadan önce kırmızı fener saatlerce pencerenin yanında parlıyordu.'::text),
(364014,40446,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A piros lámpás órák óta ... az ablaknál, mielőtt felkapcsolódott a konyhai lámpa.'::text,'világított'::text,'világít'::text,'világított'::text,'A piros lámpás órák óta világított az ablaknál, mielőtt felkapcsolódott a konyhai lámpa.'::text),
(381189,42355,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also ich hab gehört, dass der Welpe schon ..., bevor der Pitbull in seinem roten Ring vorbeitrieb.'::text,'eingeschlafen war'::text,'eingeschlafen ist'::text,'einschläft'::text,'Okay, also ich hab gehört, dass der Welpe schon eingeschlafen war, bevor der Pitbull in seinem roten Ring vorbeitrieb.'::text),
(381193,42355,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, я чула, що цуценя ... ще до того, як пітбуль пропливав повз у своєму червоному колі.'::text,'заснуло'::text,'заснуло'::text,'засинає'::text,'Коротше, я чула, що цуценя заснуло ще до того, як пітбуль пропливав повз у своєму червоному колі.'::text),
(381192,42355,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues yo oí que el cachorro ya ... antes de que el pitbull pasara flotando en su flotador rojo.'::text,'se había quedado dormido'::text,'se ha quedado dormido'::text,'se duerme'::text,'Vale, pues yo oí que el cachorro ya se había quedado dormido antes de que el pitbull pasara flotando en su flotador rojo.'::text),
(381191,42355,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon alors, j''ai entendu dire que le chiot ... avant que le pitbull ne passe en flottant dans sa bouée rouge.'::text,'s''était endormi'::text,'s''est endormi'::text,'s''endort'::text,'Bon alors, j''ai entendu dire que le chiot s''était endormi avant que le pitbull ne passe en flottant dans sa bouée rouge.'::text),
(381194,42355,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam yani, ben duydum ki pitbull kırmızı simidiyle yanından süzülüp geçmeden önce yavru köpek ...'::text,'uyuyakalmıştı'::text,'uyuyakaldı'::text,'uyuyakalır'::text,'Tamam yani, ben duydum ki pitbull kırmızı simidiyle yanından süzülüp geçmeden önce yavru köpek uyuyakalmıştı.'::text),
(381195,42355,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval én úgy hallottam, a kiskutya ..., mielőtt a pitbull elúszott mellette a piros úszógumijában.'::text,'elaludt'::text,'elaludt'::text,'elalszik'::text,'Oké, szóval én úgy hallottam, a kiskutya elaludt, mielőtt a pitbull elúszott mellette a piros úszógumijában.'::text),
(381234,42360,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als der Mann sein Handtuch aufhob, ... der Welpe schon zehn Minuten schlafend in seinem Ring.'::text,'lag'::text,'lag'::text,'liegt'::text,'Als der Mann sein Handtuch aufhob, lag der Welpe schon zehn Minuten schlafend in seinem Ring.'::text),
(381238,42360,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли чоловік узяв рушник, цуценя вже десять хвилин ... сплячим у своєму колі.'::text,'лежало'::text,'лежало'::text,'лежить'::text,'Коли чоловік узяв рушник, цуценя вже десять хвилин лежало сплячим у своєму колі.'::text),
(381237,42360,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando el hombre cogió su toalla, el cachorro ya ... diez minutos dormido en su flotador.'::text,'llevaba'::text,'estaba'::text,'lleva'::text,'Cuando el hombre cogió su toalla, el cachorro ya llevaba diez minutos dormido en su flotador.'::text),
(381236,42360,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand l''homme a ramassé sa serviette, le chiot ... endormi dans sa bouée depuis dix minutes.'::text,'était'::text,'était'::text,'est'::text,'Quand l''homme a ramassé sa serviette, le chiot était endormi dans sa bouée depuis dix minutes.'::text),
(381239,42360,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam havlusunu aldığında yavru köpek on dakikadır simidinde uyur halde ...'::text,'yatıyordu'::text,'yatıyordu'::text,'yatıyor'::text,'Adam havlusunu aldığında yavru köpek on dakikadır simidinde uyur halde yatıyordu.'::text),
(381240,42360,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a férfi felvette a törölközőjét, a kiskutya már tíz perce ... alva az úszógumijában.'::text,'feküdt'::text,'feküdt'::text,'fekszik'::text,'Mire a férfi felvette a törölközőjét, a kiskutya már tíz perce feküdt alva az úszógumijában.'::text),
(339726,37748,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Turm keinen Ball hätte, ... das Kätzchen gar nichts, weil es keinen Ball gäbe.'::text,'jagte'::text,'jagt'::text,'jagte'::text,'Wenn der Turm keinen Ball hätte, jagte das Kätzchen gar nichts, weil es keinen Ball gäbe.'::text),
(339730,37748,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби в башті не було м''ячика, кошеня ... ні за чим, бо не було б м''ячика.'::text,'не ганялося б'::text,'не ганятиметься'::text,'не ганялося'::text,'Якби в башті не було м''ячика, кошеня не ганялося б ні за чим, бо не було б м''ячика.'::text),
(339729,37748,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la torre no tuviera pelota, el gatito no ... nada, porque no habría pelota.'::text,'perseguiría'::text,'perseguirá'::text,'persiguió'::text,'Si la torre no tuviera pelota, el gatito no perseguiría nada, porque no habría pelota.'::text),
(339728,37748,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la tour n''avait pas de balle, le chaton ne ... rien, parce qu''il n''y aurait pas de balle.'::text,'poursuivrait'::text,'poursuivra'::text,'poursuivait'::text,'Si la tour n''avait pas de balle, le chaton ne poursuivrait rien, parce qu''il n''y aurait pas de balle.'::text),
(339731,37748,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kulede top olmasaydı, yavru kedi hiçbir şeyi ..., çünkü top olmazdı.'::text,'kovalamazdı'::text,'kovalamayacak'::text,'kovalamadı'::text,'Kulede top olmasaydı, yavru kedi hiçbir şeyi kovalamazdı, çünkü top olmazdı.'::text),
(339732,37748,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a toronyban nem lenne labda, a kiscica semmit sem ..., mert nem lenne labda.'::text,'kergetne'::text,'fog kergetni'::text,'kergetett'::text,'Ha a toronyban nem lenne labda, a kiscica semmit sem kergetne, mert nem lenne labda.'::text),
(339753,37751,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Kätzchen ... den Ball ganze fünf Minuten, bevor es ihn fing. Ein echter Profi.'::text,'jagte'::text,'jagt'::text,'jagt'::text,'Das Kätzchen jagte den Ball ganze fünf Minuten, bevor es ihn fing. Ein echter Profi.'::text),
(339757,37751,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кошеня ... за м''ячиком цілих п''ять хвилин, перш ніж його впіймало. Справжній профі.'::text,'ганялося'::text,'ганяється'::text,'ганяється'::text,'Кошеня ганялося за м''ячиком цілих п''ять хвилин, перш ніж його впіймало. Справжній профі.'::text),
(339756,37751,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El gatito ... la pelota cinco minutos enteros antes de atraparla. Todo un profesional.'::text,'había estado persiguiendo'::text,'ha estado persiguiendo'::text,'persigue'::text,'El gatito había estado persiguiendo la pelota cinco minutos enteros antes de atraparla. Todo un profesional.'::text),
(339755,37751,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chaton ... la balle pendant cinq bonnes minutes avant de l''attraper. Un vrai pro.'::text,'avait poursuivi'::text,'a poursuivi'::text,'poursuit'::text,'Le chaton avait poursuivi la balle pendant cinq bonnes minutes avant de l''attraper. Un vrai pro.'::text),
(339758,37751,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yavru kedi, yakalamadan önce topu tam beş dakika ..., tam bir profesyonel.'::text,'kovalamıştı'::text,'kovaladı'::text,'kovalar'::text,'Yavru kedi, yakalamadan önce topu tam beş dakika kovalamıştı, tam bir profesyonel.'::text),
(339759,37751,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kiscica öt teljes percig ... a labdát, mielőtt elkapta. Igazi profi.'::text,'kergette'::text,'kergeti'::text,'kergeti'::text,'A kiscica öt teljes percig kergette a labdát, mielőtt elkapta. Igazi profi.'::text),
(373881,41543,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Kuh bestritt natürlich, den ganzen Kuchen ..., während sie sich über den leeren Teller beugte.'::text,'gegessen zu haben'::text,'zu essen'::text,'aß'::text,'Die Kuh bestritt natürlich, den ganzen Kuchen gegessen zu haben, während sie sich über den leeren Teller beugte.'::text),
(373885,41543,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Корова, звісно, заперечувала, що ... весь пиріг, нахилившись над порожньою тарілкою.'::text,'з''їла'::text,'з''їсти'::text,'з''їла'::text,'Корова, звісно, заперечувала, що з''їла весь пиріг, нахилившись над порожньою тарілкою.'::text),
(373884,41543,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La vaca negó ... el pastel entero, obviamente, mientras se inclinaba sobre el plato vacío.'::text,'haberse comido'::text,'comer'::text,'comió'::text,'La vaca negó haberse comido el pastel entero, obviamente, mientras se inclinaba sobre el plato vacío.'::text),
(373883,41543,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La vache a nié ... toute la tarte, évidemment, en se penchant au-dessus de l''assiette vide.'::text,'avoir mangé'::text,'manger'::text,'a mangé'::text,'La vache a nié avoir mangé toute la tarte, évidemment, en se penchant au-dessus de l''assiette vide.'::text),
(373886,41543,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İnek, boş tabağın üzerine eğilirken, tabii ki bütün turtayı ... inkâr etti.'::text,'yediğini'::text,'yemeyi'::text,'yedi'::text,'İnek, boş tabağın üzerine eğilirken, tabii ki bütün turtayı yediğini inkâr etti.'::text),
(373887,41543,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tehén persze tagadta, hogy ... az egész pitét, miközben az üres tányér fölé hajolt.'::text,'megette'::text,'megenni'::text,'megette'::text,'A tehén persze tagadta, hogy megette az egész pitét, miközben az üres tányér fölé hajolt.'::text),
(363639,40405,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn diese Flasche mich von meinem Block ..., wäre das das Ende von allem!'::text,'stoßen würde'::text,'stößt'::text,'stoßen würde'::text,'Wenn diese Flasche mich von meinem Block stoßen würde, wäre das das Ende von allem!'::text),
(363643,40405,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби та пляшка ... мене з мого блока, це був би кінець усього!'::text,'збила'::text,'зб''є'::text,'збила б'::text,'Якби та пляшка збила мене з мого блока, це був би кінець усього!'::text),
(363642,40405,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si esa botella me ... de mi bloque, sería el fin de todo!'::text,'tirara'::text,'tira'::text,'tiraría'::text,'¡Si esa botella me tirara de mi bloque, sería el fin de todo!'::text),
(363641,40405,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si cette bouteille me ... de mon bloc, ce serait la fin de tout !'::text,'faisait tomber'::text,'fait tomber'::text,'ferait tomber'::text,'Si cette bouteille me faisait tomber de mon bloc, ce serait la fin de tout !'::text),
(363644,40405,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O şişe beni bloğumdan ..., her şeyin sonu olurdu!'::text,'düşürseydi'::text,'düşürür'::text,'düşürürdü'::text,'O şişe beni bloğumdan düşürseydi, her şeyin sonu olurdu!'::text),
(363645,40405,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az a palack ... a blokkomról, az lenne mindennek a vége!'::text,'leverne'::text,'lever'::text,'leverne'::text,'Ha az a palack leverne a blokkomról, az lenne mindennek a vége!'::text),
(363666,40408,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als die Flasche ihn umwarf, ... seine Freunde sie schon fünf Minuten hin und her.'::text,'schwangen'::text,'schwangen'::text,'schwangen'::text,'Als die Flasche ihn umwarf, schwangen seine Freunde sie schon fünf Minuten hin und her.'::text),
(363670,40408,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли пляшка збила його, його друзі ... її вже п''ять хвилин.'::text,'розгойдували'::text,'розгойдали'::text,'розгойдували'::text,'Коли пляшка збила його, його друзі розгойдували її вже п''ять хвилин.'::text),
(363669,40408,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando la botella lo tiró, sus amigos ... durante cinco minutos.'::text,'la habían estado balanceando'::text,'la balancearon'::text,'la estaban balanceando'::text,'Cuando la botella lo tiró, sus amigos la habían estado balanceando durante cinco minutos.'::text),
(363668,40408,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand la bouteille l''a renversé, ses amis la ... depuis cinq minutes.'::text,'balançaient'::text,'ont balancée'::text,'balançaient'::text,'Quand la bouteille l''a renversé, ses amis la balançaient depuis cinq minutes.'::text),
(363671,40408,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şişe onu devirdiğinde, arkadaşları onu beş dakikadır ...'::text,'sallıyordu'::text,'salladı'::text,'sallıyordu'::text,'Şişe onu devirdiğinde, arkadaşları onu beş dakikadır sallıyordu.'::text),
(363672,40408,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amikor a palack feldöntötte, a barátai már öt perce ... azt.'::text,'lengették'::text,'meglengették'::text,'lengették'::text,'Amikor a palack feldöntötte, a barátai már öt perce lengették azt.'::text),
(397416,44158,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der oberste Ball ... quer über den Tisch, und keiner konnte es glauben!'::text,'wurde geworfen'::text,'warf'::text,'wird geworfen'::text,'Der oberste Ball wurde geworfen quer über den Tisch, und keiner konnte es glauben!'::text),
(397420,44158,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Верхній м''ячик ... з іншого боку столу, і ніхто в це не повірив!'::text,'був кинутий'::text,'кинув'::text,'кидають'::text,'Верхній м''ячик був кинутий з іншого боку столу, і ніхто в це не повірив!'::text),
(397419,44158,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La pelota de arriba ... desde el otro lado de la mesa, y nadie se lo creyó!'::text,'fue lanzada'::text,'lanzó'::text,'es lanzada'::text,'¡La pelota de arriba fue lanzada desde el otro lado de la mesa, y nadie se lo creyó!'::text),
(397418,44158,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La balle du haut ... depuis l''autre bout de la table, et personne n''y a cru !'::text,'a été lancée'::text,'a lancé'::text,'est lancée'::text,'La balle du haut a été lancée depuis l''autre bout de la table, et personne n''y a cru !'::text),
(397421,44158,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En üstteki top masanın öbür ucundan ... ve kimse buna inanmadı!'::text,'atıldı'::text,'attı'::text,'atılıyor'::text,'En üstteki top masanın öbür ucundan atıldı ve kimse buna inanmadı!'::text),
(397422,44158,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A legfelső labdát ... az asztal túloldaláról, és senki sem hitte el!'::text,'dobták'::text,'dobta'::text,'dobják'::text,'A legfelső labdát dobták az asztal túloldaláról, és senki sem hitte el!'::text),
(397488,44166,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der oberste Ball ... das Ziel um 19:42 Uhr, und der Stapel blieb stehen.'::text,'traf'::text,'traf gerade'::text,'hatte getroffen'::text,'Der oberste Ball traf das Ziel um 19:42 Uhr, und der Stapel blieb stehen.'::text),
(397492,44166,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Верхній м''ячик ... у ціль о 19:42, і стос устояв.'::text,'влучив'::text,'влучав'::text,'влучав'::text,'Верхній м''ячик влучив у ціль о 19:42, і стос устояв.'::text),
(397491,44166,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pelota de arriba ... el objetivo a las 19:42, y la pila se mantuvo en pie.'::text,'alcanzó'::text,'estaba alcanzando'::text,'había estado alcanzando'::text,'La pelota de arriba alcanzó el objetivo a las 19:42, y la pila se mantuvo en pie.'::text),
(397490,44166,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La balle du haut ... la cible à 19 h 42, et la pile est restée debout.'::text,'a atteint'::text,'atteignait'::text,'avait atteint'::text,'La balle du haut a atteint la cible à 19 h 42, et la pile est restée debout.'::text),
(397493,44166,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En üstteki top saat 19:42''de hedefi ... ve yığın ayakta kaldı.'::text,'vurdu'::text,'vuruyordu'::text,'vurmuştu'::text,'En üstteki top saat 19:42''de hedefi vurdu ve yığın ayakta kaldı.'::text),
(397494,44166,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A legfelső labda 19:42-kor ... a célt, és a torony állva maradt.'::text,'eltalálta'::text,'éppen találta el'::text,'eltalálta'::text,'A legfelső labda 19:42-kor eltalálta a célt, és a torony állva maradt.'::text),
(368472,40942,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit wird er diese schreckliche Sauerei für immer aus seinen Haaren ...!'::text,'waschen'::text,'waschen'::text,'wäscht'::text,'Morgen um diese Zeit wird er diese schreckliche Sauerei für immer aus seinen Haaren waschen!'::text),
(368476,40942,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час він ... цей жахливий безлад зі свого волосся назавжди!'::text,'вимиватиме'::text,'вимиє'::text,'вимиває'::text,'Завтра в цей час він вимиватиме цей жахливий безлад зі свого волосся назавжди!'::text),
(368475,40942,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Mañana a esta hora él ... este horrible desastre de su pelo para siempre!'::text,'estará lavándose'::text,'se lavará'::text,'se lava'::text,'¡Mañana a esta hora él estará lavándose este horrible desastre de su pelo para siempre!'::text),
(368474,40942,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à cette heure-ci, il ... cette horrible saleté de ses cheveux pour toujours !'::text,'sera en train d''enlever'::text,'enlèvera'::text,'enlève'::text,'Demain à cette heure-ci, il sera en train d''enlever cette horrible saleté de ses cheveux pour toujours !'::text),
(368477,40942,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte o, bu korkunç pisliği saçından sonsuza dek ...!'::text,'yıkıyor olacak'::text,'yıkayacak'::text,'yıkar'::text,'Yarın bu saatte o, bu korkunç pisliği saçından sonsuza dek yıkıyor olacak!'::text),
(368478,40942,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor ő ... ezt a szörnyű trutyit a hajából, örökre!'::text,'épp kimossa'::text,'ki fogja mosni'::text,'kimossa'::text,'Holnap ilyenkor ő épp kimossa ezt a szörnyű trutyit a hajából, örökre!'::text),
(368553,40951,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Grüner Schleim ... von seinen Haaren in die Box, und die Sauerei wird immer größer.'::text,'tropft'::text,'tropft'::text,'ist getropft'::text,'Grüner Schleim tropft von seinen Haaren in die Box, und die Sauerei wird immer größer.'::text),
(368557,40951,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зелений слиз ... з його волосся в коробку, і безлад усе росте.'::text,'капає'::text,'капає'::text,'накапав'::text,'Зелений слиз капає з його волосся в коробку, і безлад усе росте.'::text),
(368556,40951,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El slime verde ... de su pelo a la caja, y el desastre no para de crecer.'::text,'está goteando'::text,'gotea'::text,'ha goteado'::text,'El slime verde está goteando de su pelo a la caja, y el desastre no para de crecer.'::text),
(368555,40951,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du slime vert ... de ses cheveux dans la boîte, et le bazar ne cesse de grandir.'::text,'dégouline'::text,'dégouline'::text,'a dégouliné'::text,'Du slime vert dégouline de ses cheveux dans la boîte, et le bazar ne cesse de grandir.'::text),
(368558,40951,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yeşil slime saçından kutuya ... ve dağınıklık büyümeye devam ediyor.'::text,'damlıyor'::text,'damlar'::text,'damladı'::text,'Yeşil slime saçından kutuya damlıyor ve dağınıklık büyümeye devam ediyor.'::text),
(368559,40951,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A zöld slime ... a hajából a dobozba, és a kupi egyre nő.'::text,'csöpög'::text,'csöpög'::text,'lecsöpögött'::text,'A zöld slime csöpög a hajából a dobozba, és a kupi egyre nő.'::text),
(344091,38233,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... sie mit dem roten Band über dieselbe Bahn.'::text,'kriechen'::text,'kriechen'::text,'kriechen'::text,'Morgen um diese Zeit kriechen sie mit dem roten Band über dieselbe Bahn.'::text),
(344095,38233,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час вони ... тією самою доріжкою з червоною резинкою.'::text,'повзтимуть'::text,'проповзуть'::text,'повзуть'::text,'Завтра в цей час вони повзтимуть тією самою доріжкою з червоною резинкою.'::text),
(344094,38233,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora ellos ... por la misma pista con la banda roja.'::text,'estarán gateando'::text,'gatearán'::text,'gatean'::text,'Mañana a esta hora ellos estarán gateando por la misma pista con la banda roja.'::text),
(344093,38233,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à cette heure-ci, ils ... sur la même piste avec l''élastique rouge.'::text,'seront en train de ramper'::text,'ramperont'::text,'rampent'::text,'Demain à cette heure-ci, ils seront en train de ramper sur la même piste avec l''élastique rouge.'::text),
(344096,38233,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte onlar kırmızı bantla aynı pistte ...'::text,'sürünüyor olacaklar'::text,'sürünecekler'::text,'sürünürler'::text,'Yarın bu saatte onlar kırmızı bantla aynı pistte sürünüyor olacaklar.'::text),
(344097,38233,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor ők ugyanazon a pályán ... a piros gumiszalaggal.'::text,'mászni fognak'::text,'másznak majd'::text,'másznak'::text,'Holnap ilyenkor ők ugyanazon a pályán mászni fognak a piros gumiszalaggal.'::text),
(344181,38243,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... erst ein paar Meter, als das Band sie flach auf die Bahn zog.'::text,'waren gekrochen'::text,'sind gekrochen'::text,'krochen'::text,'Sie waren gekrochen erst ein paar Meter, als das Band sie flach auf die Bahn zog.'::text),
(344185,38243,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... лише кілька метрів, коли резинка притягнула її плазом на доріжку.'::text,'проповзли'::text,'проповзли'::text,'проповзли'::text,'Вони проповзли лише кілька метрів, коли резинка притягнула її плазом на доріжку.'::text),
(344184,38243,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ellos ... solo unos metros cuando la banda la tiró al suelo de la pista.'::text,'habían gateado'::text,'han gateado'::text,'gatearon'::text,'Ellos habían gateado solo unos metros cuando la banda la tiró al suelo de la pista.'::text),
(344183,38243,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... seulement quelques mètres quand l''élastique l''a plaquée au sol sur la piste.'::text,'avaient rampé'::text,'ont rampé'::text,'ont rampé'::text,'Ils avaient rampé seulement quelques mètres quand l''élastique l''a plaquée au sol sur la piste.'::text),
(344186,38243,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar sadece birkaç metre ... ki bant onu pistin üstüne yapıştırdı.'::text,'sürünmüşlerdi'::text,'süründüler'::text,'süründüler'::text,'Onlar sadece birkaç metre sürünmüşlerdi ki bant onu pistin üstüne yapıştırdı.'::text),
(344187,38243,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ők még csak néhány métert ..., amikor a gumiszalag a pályára rántotta a lányt.'::text,'kúsztak'::text,'kúsztak'::text,'kúsztak'::text,'Ők még csak néhány métert kúsztak, amikor a gumiszalag a pályára rántotta a lányt.'::text),
(394509,43835,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Blumen haben sie überrascht, weil sie sie nicht erwartet hat, und ...'::text,'ich auch nicht'::text,'ich auch'::text,'ich auch nicht'::text,'Die Blumen haben sie überrascht, weil sie sie nicht erwartet hat, und ich auch nicht.'::text),
(394513,43835,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Квіти її здивували, бо вона їх не чекала, і ...'::text,'я теж ні'::text,'я теж'::text,'я теж ні'::text,'Квіти її здивували, бо вона їх не чекала, і я теж ні.'::text),
(394512,43835,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las flores la sorprendieron porque ella no las esperaba, y ...'::text,'yo tampoco'::text,'yo también'::text,'yo tampoco'::text,'Las flores la sorprendieron porque ella no las esperaba, y yo tampoco.'::text),
(394511,43835,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les fleurs l''ont surprise parce qu''elle ne les attendait pas, et ...'::text,'moi non plus'::text,'moi aussi'::text,'moi non plus'::text,'Les fleurs l''ont surprise parce qu''elle ne les attendait pas, et moi non plus.'::text),
(394514,43835,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çiçekler onu şaşırttı çünkü o onları beklemiyordu, ve ...'::text,'ben de beklemiyordum'::text,'ben de bekliyordum'::text,'ben de beklemiyordum'::text,'Çiçekler onu şaşırttı çünkü o onları beklemiyordu, ve ben de beklemiyordum.'::text),
(394515,43835,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A virágok meglepték, mert ő nem számított rájuk, és ...'::text,'én sem'::text,'én is'::text,'én sem'::text,'A virágok meglepték, mert ő nem számított rájuk, és én sem.'::text),
(394554,43840,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ließ die Floristin die Pfingstrosen in rosa Band ..., um sie zu überraschen.'::text,'einpacken'::text,'einpacken'::text,'eingepackt'::text,'Er ließ die Floristin die Pfingstrosen in rosa Band einpacken, um sie zu überraschen.'::text),
(394558,43840,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він попросив флористку ... півонії в рожеву стрічку, щоб її здивувати.'::text,'загорнути'::text,'загорнути'::text,'загорнуті'::text,'Він попросив флористку загорнути півонії в рожеву стрічку, щоб її здивувати.'::text),
(394557,43840,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él hizo que la florista ... las peonías con una cinta rosa para sorprenderla.'::text,'envolviera'::text,'envolviera'::text,'envueltas'::text,'Él hizo que la florista envolviera las peonías con una cinta rosa para sorprenderla.'::text),
(394556,43840,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a fait ... les pivoines dans un ruban rose par la fleuriste pour la surprendre.'::text,'emballer'::text,'emballer'::text,'emballées'::text,'Il a fait emballer les pivoines dans un ruban rose par la fleuriste pour la surprendre.'::text),
(394559,43840,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, onu şaşırtmak için şakayıkları çiçekçiye pembe kurdeleyle ...'::text,'sardırdı'::text,'sardırdı'::text,'sarılmış'::text,'O, onu şaşırtmak için şakayıkları çiçekçiye pembe kurdeleyle sardırdı.'::text),
(394560,43840,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő a virágárussal pink szalagba ... a bazsarózsákat, hogy meglepje.'::text,'csomagoltatta'::text,'csomagoltatta'::text,'becsomagolva'::text,'Ő a virágárussal pink szalagba csomagoltatta a bazsarózsákat, hogy meglepje.'::text),
(379650,42184,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Männchen ... die Bitte mit erhobenem Zeigefinger, wie beobachtet.'::text,'verweigerte'::text,'wurde verweigert'::text,'verweigernd'::text,'Das Männchen verweigerte die Bitte mit erhobenem Zeigefinger, wie beobachtet.'::text),
(379654,42184,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Самець ... прохання піднятим вказівним пальцем, як було зафіксовано.'::text,'відхилив'::text,'був відхилений'::text,'відхиляючи'::text,'Самець відхилив прохання піднятим вказівним пальцем, як було зафіксовано.'::text),
(379653,42184,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El macho ... la petición con el dedo índice levantado, según lo observado.'::text,'rechazó'::text,'fue rechazado'::text,'rechazando'::text,'El macho rechazó la petición con el dedo índice levantado, según lo observado.'::text),
(379652,42184,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le mâle ... la demande d''un index levé, comme observé.'::text,'a refusé'::text,'a été refusé'::text,'refusant'::text,'Le mâle a refusé la demande d''un index levé, comme observé.'::text),
(379655,42184,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Erkek birey, gözlemlendiği üzere, isteği kaldırılmış işaret parmağıyla ...'::text,'reddetti'::text,'reddedildi'::text,'reddederek'::text,'Erkek birey, gözlemlendiği üzere, isteği kaldırılmış işaret parmağıyla reddetti.'::text),
(379656,42184,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hím egyed ... a kérést felemelt mutatóujjal, ahogy megfigyelték.'::text,'elutasította'::text,'el lett utasítva'::text,'elutasítva'::text,'A hím egyed elutasította a kérést felemelt mutatóujjal, ahogy megfigyelték.'::text),
(362271,40253,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Besitzer Solarmodule aufs Dach ..., erzeugt der Van seinen eigenen Strom.'::text,'installieren'::text,'installierten'::text,'installieren werden'::text,'Wenn die Besitzer Solarmodule aufs Dach installieren, erzeugt der Van seinen eigenen Strom.'::text),
(362275,40253,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо власники ... сонячні панелі на дах, фургон виробляє власну електрику.'::text,'встановлюють'::text,'встановили'::text,'встановлять'::text,'Якщо власники встановлюють сонячні панелі на дах, фургон виробляє власну електрику.'::text),
(362274,40253,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si los dueños ... paneles solares en el techo, la furgoneta produce su propia energía.'::text,'instalan'::text,'instalaron'::text,'instalarán'::text,'Si los dueños instalan paneles solares en el techo, la furgoneta produce su propia energía.'::text),
(362273,40253,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si les propriétaires ... des panneaux solaires sur le toit, le van produit sa propre électricité.'::text,'installent'::text,'installaient'::text,'installeront'::text,'Si les propriétaires installent des panneaux solaires sur le toit, le van produit sa propre électricité.'::text),
(362276,40253,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sahipler çatıya güneş panelleri ..., minibüs kendi elektriğini üretir.'::text,'takarsa'::text,'taktıysa'::text,'takacaksa'::text,'Sahipler çatıya güneş panelleri takarsa, minibüs kendi elektriğini üretir.'::text),
(362277,40253,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a tulajdonosok napelemeket ... a tetőre, a furgon saját áramot termel.'::text,'szerelnek'::text,'szereltek'::text,'fognak szerelni'::text,'Ha a tulajdonosok napelemeket szerelnek a tetőre, a furgon saját áramot termel.'::text),
(362334,40260,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie weigerten sich, die Dusche von einem Profi ... zu lassen, und es war fast eine Katastrophe!'::text,'installieren'::text,'installieren'::text,'zu installieren'::text,'Sie weigerten sich, die Dusche von einem Profi installieren zu lassen, und es war fast eine Katastrophe!'::text),
(362338,40260,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони відмовилися від того, щоб душ ... професіонал, і це була майже катастрофа!'::text,'встановив'::text,'встановив'::text,'встановити'::text,'Вони відмовилися від того, щоб душ встановив професіонал, і це була майже катастрофа!'::text),
(362337,40260,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ellos se negaron a que un profesional les ... la ducha, y casi fue un desastre!'::text,'instalara'::text,'instalara'::text,'instalar'::text,'¡Ellos se negaron a que un profesional les instalara la ducha, y casi fue un desastre!'::text),
(362336,40260,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ont refusé de faire ... la douche par un pro, et ça a failli tourner à la catastrophe !'::text,'installer'::text,'installer'::text,'installer'::text,'Ils ont refusé de faire installer la douche par un pro, et ça a failli tourner à la catastrophe !'::text),
(362339,40260,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar duşu bir profesyonele ... reddettiler ve neredeyse felaket oldu!'::text,'taktırmayı'::text,'takmayı'::text,'takmayı'::text,'Onlar duşu bir profesyonele taktırmayı reddettiler ve neredeyse felaket oldu!'::text),
(362340,40260,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ők nem voltak hajlandók szakemberrel ... a zuhanyt, és majdnem katasztrófa lett belőle!'::text,'beszereltetni'::text,'beszerelni'::text,'beszerelni'::text,'Ők nem voltak hajlandók szakemberrel beszereltetni a zuhanyt, és majdnem katasztrófa lett belőle!'::text),
(370020,41114,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, angeblich ist das Motorrad mit einem speziellen Träger am Truck ...'::text,'befestigt'::text,'am Befestigen'::text,'befestigte'::text,'Hör mal, angeblich ist das Motorrad mit einem speziellen Träger am Truck befestigt.'::text),
(370024,41114,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, той мотоцикл ... до вантажівки спеціальним кріпленням.'::text,'прикріплений'::text,'прикріплює'::text,'прикріпив'::text,'Слухай, кажуть, той мотоцикл прикріплений до вантажівки спеціальним кріпленням.'::text),
(370023,41114,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer esa moto ... al camión con un soporte especial.'::text,'está sujeta'::text,'está sujetando'::text,'sujetó'::text,'Oye, al parecer esa moto está sujeta al camión con un soporte especial.'::text),
(370022,41114,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment cette moto ... au camion avec un support spécial.'::text,'est fixée'::text,'est en train de fixer'::text,'a fixé'::text,'Écoute, apparemment cette moto est fixée au camion avec un support spécial.'::text),
(370025,41114,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duyduğuma göre o motosiklet kamyona özel bir rafla ...'::text,'bağlı'::text,'bağlıyor'::text,'bağladı'::text,'Dinle, duyduğuma göre o motosiklet kamyona özel bir rafla bağlı.'::text),
(370026,41114,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag az a motor egy speciális tartóval ... a teherautóhoz.'::text,'van rögzítve'::text,'rögzít'::text,'rögzítette'::text,'Figyelj, állítólag az a motor egy speciális tartóval van rögzítve a teherautóhoz.'::text),
(370047,41117,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nächsten Monat um diese Zeit wird er das Motorrad auf Hunderten kurzer Trips ...'::text,'gefahren haben'::text,'fahren'::text,'fährt'::text,'Nächsten Monat um diese Zeit wird er das Motorrad auf Hunderten kurzer Trips gefahren haben.'::text),
(370051,41117,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Наступного місяця в цей час він ... сотні коротких поїздок на мотоциклі.'::text,'здійснить'::text,'здійснюватиме'::text,'здійснює'::text,'Наступного місяця в цей час він здійснить сотні коротких поїздок на мотоциклі.'::text),
(370050,41117,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El mes que viene a estas alturas, él ... la moto en cientos de viajes cortos.'::text,'habrá conducido'::text,'conducirá'::text,'conduce'::text,'El mes que viene a estas alturas, él habrá conducido la moto en cientos de viajes cortos.'::text),
(370049,41117,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le mois prochain à la même époque, il ... la moto pour des centaines de petits trajets.'::text,'aura pris'::text,'prendra'::text,'prend'::text,'D''ici le mois prochain à la même époque, il aura pris la moto pour des centaines de petits trajets.'::text),
(370052,41117,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gelecek ay bu zamana kadar o, motosikletle yüzlerce kısa yolculuk ...'::text,'yapmış olacak'::text,'yapacak'::text,'yapar'::text,'Gelecek ay bu zamana kadar o, motosikletle yüzlerce kısa yolculuk yapmış olacak.'::text),
(370053,41117,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jövő hónap ilyenkorra ő már több száz rövid utat ... a motorral.'::text,'megtett'::text,'fog megtenni'::text,'tesz meg'::text,'Jövő hónap ilyenkorra ő már több száz rövid utat megtett a motorral.'::text),
(363306,40368,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Exemplar scheint es zu genießen, spätnachts auf der Tastatur ...'::text,'zu tippen'::text,'zu tippen'::text,'tippen'::text,'Das Exemplar scheint es zu genießen, spätnachts auf der Tastatur zu tippen.'::text),
(363310,40368,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Схоже, особині подобається ... по клавіатурі пізно вночі.'::text,'стукати'::text,'стукати'::text,'стукати'::text,'Схоже, особині подобається стукати по клавіатурі пізно вночі.'::text),
(363309,40368,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El espécimen parece disfrutar ... en el teclado a altas horas de la noche.'::text,'tecleando'::text,'teclear'::text,'teclear'::text,'El espécimen parece disfrutar tecleando en el teclado a altas horas de la noche.'::text),
(363308,40368,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le spécimen semble aimer ... sur le clavier tard dans la nuit.'::text,'taper'::text,'taper'::text,'taper'::text,'Le spécimen semble aimer taper sur le clavier tard dans la nuit.'::text),
(363311,40368,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Numunenin gece geç saatlerde klavyede ... hoşlandığı görülüyor.'::text,'tıklamaktan'::text,'tıklamak'::text,'tıkla'::text,'Numunenin gece geç saatlerde klavyede tıklamaktan hoşlandığı görülüyor.'::text),
(363312,40368,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy tűnik, a példány élvezi a késő éjjeli ... a billentyűzeten.'::text,'kopogást'::text,'kopogni'::text,'kopog'::text,'Úgy tűnik, a példány élvezi a késő éjjeli kopogást a billentyűzeten.'::text),
(363324,40370,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als die Kamera heranzoomte, ... der Hund schon seit Stunden an der Tastatur.'::text,'saß'::text,'saß'::text,'saß'::text,'Als die Kamera heranzoomte, saß der Hund schon seit Stunden an der Tastatur.'::text),
(363328,40370,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли камера наблизила кадр, пес уже кілька годин ... за клавіатурою.'::text,'сидів'::text,'сидів'::text,'сидів'::text,'Коли камера наблизила кадр, пес уже кілька годин сидів за клавіатурою.'::text),
(363327,40370,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando la cámara hizo zoom, el perro ya ... horas sentado frente al teclado.'::text,'llevaba'::text,'estaba'::text,'se sentó'::text,'Cuando la cámara hizo zoom, el perro ya llevaba horas sentado frente al teclado.'::text),
(363326,40370,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand la caméra a zoomé, le chien ... devant le clavier depuis des heures.'::text,'était assis'::text,'était assis'::text,'s''est assis'::text,'Quand la caméra a zoomé, le chien était assis devant le clavier depuis des heures.'::text),
(363329,40370,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kamera yakınlaştırdığında köpek saatlerdir klavyenin başında ...'::text,'oturuyordu'::text,'oturuyordu'::text,'oturdu'::text,'Kamera yakınlaştırdığında köpek saatlerdir klavyenin başında oturuyordu.'::text),
(363330,40370,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a kamera ráközelített, a kutya már órák óta ... a billentyűzetnél.'::text,'ült'::text,'ült'::text,'ült'::text,'Mire a kamera ráközelített, a kutya már órák óta ült a billentyűzetnél.'::text),
(352416,39158,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jemand hat den Pavianen eine Banane auf der Motorhaube gegeben, ...?'::text,'oder'::text,'echt'::text,'oder'::text,'Jemand hat den Pavianen eine Banane auf der Motorhaube gegeben, oder?'::text),
(352420,39158,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хтось нагодував павіанів бананом на капоті, ...?'::text,'так'::text,'справді'::text,'так'::text,'Хтось нагодував павіанів бананом на капоті, так?'::text),
(352419,39158,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alguien les dio un plátano a los babuinos en el capó, ¿...?'::text,'verdad'::text,'en serio'::text,'verdad'::text,'Alguien les dio un plátano a los babuinos en el capó, ¿verdad?'::text),
(352418,39158,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quelqu''un a donné une banane aux babouins sur le capot, ... ?'::text,'non'::text,'vraiment'::text,'non'::text,'Quelqu''un a donné une banane aux babouins sur le capot, non ?'::text),
(352421,39158,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biri babunlara kaputun üstünde muz yedirdi, ...?'::text,'değil mi'::text,'gerçekten mi'::text,'değil mi'::text,'Biri babunlara kaputun üstünde muz yedirdi, değil mi?'::text),
(352422,39158,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Valaki banánt adott a páviánoknak a motorháztetőn, ...?'::text,'ugye'::text,'tényleg'::text,'ugye'::text,'Valaki banánt adott a páviánoknak a motorháztetőn, ugye?'::text),
(352470,39164,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, wir haben den Fahrer dazu gebracht, die Paviane ..., weil''s sonst keiner gemacht hätte.'::text,'zu füttern'::text,'füttern'::text,'gefüttert'::text,'Yo, wir haben den Fahrer dazu gebracht, die Paviane zu füttern, weil''s sonst keiner gemacht hätte.'::text),
(352474,39164,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, ми вмовили водія ... павіанів, бо більше ніхто б цього не зробив.'::text,'нагодувати'::text,'нагодувати'::text,'нагодував'::text,'Йо, ми вмовили водія нагодувати павіанів, бо більше ніхто б цього не зробив.'::text),
(352473,39164,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, nosotros conseguimos que el conductor ... a los babuinos, porque nadie más lo iba a hacer.'::text,'diera de comer'::text,'diera de comer'::text,'dio de comer'::text,'Oye, nosotros conseguimos que el conductor diera de comer a los babuinos, porque nadie más lo iba a hacer.'::text),
(352472,39164,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, on a convaincu le chauffeur de ... les babouins, parce que personne d''autre n''allait le faire.'::text,'nourrir'::text,'nourrir'::text,'nourri'::text,'Yo, on a convaincu le chauffeur de nourrir les babouins, parce que personne d''autre n''allait le faire.'::text),
(352475,39164,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, biz şoförü babunları ... ikna ettik, çünkü başka kimse yapmayacaktı.'::text,'beslemeye'::text,'beslemeye'::text,'besledi'::text,'Kanka, biz şoförü babunları beslemeye ikna ettik, çünkü başka kimse yapmayacaktı.'::text),
(352476,39164,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, mi rávettük a sofőrt, hogy ... a páviánokat, mert más úgysem csinálta volna meg.'::text,'megetesse'::text,'megetesse'::text,'megetette'::text,'Tesó, mi rávettük a sofőrt, hogy megetesse a páviánokat, mert más úgysem csinálta volna meg.'::text),
(354981,39443,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Strömung so stark bleibt, ... das Team sein 10-Minuten-Ziel.'::text,'übertrifft'::text,'übertrifft'::text,'übertraf'::text,'Wenn die Strömung so stark bleibt, übertrifft das Team sein 10-Minuten-Ziel.'::text),
(354985,39443,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо течія залишиться такою сильною, команда ... свою 10-хвилинну ціль.'::text,'перевершить'::text,'перевершила б'::text,'перевершила'::text,'Якщо течія залишиться такою сильною, команда перевершить свою 10-хвилинну ціль.'::text),
(354984,39443,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el caudal sigue así de fuerte, el equipo ... su objetivo de 10 minutos.'::text,'superará'::text,'superaría'::text,'superó'::text,'Si el caudal sigue así de fuerte, el equipo superará su objetivo de 10 minutos.'::text),
(354983,39443,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le courant reste aussi fort, l''équipe ... son objectif de 10 minutes.'::text,'battra'::text,'battrait'::text,'a battu'::text,'Si le courant reste aussi fort, l''équipe battra son objectif de 10 minutes.'::text),
(354986,39443,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Akış bu kadar güçlü kalırsa, ekip 10 dakikalık hedefini ...'::text,'geçecek'::text,'geçerdi'::text,'geçti'::text,'Akış bu kadar güçlü kalırsa, ekip 10 dakikalık hedefini geçecek.'::text),
(354987,39443,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a sodrás ilyen erős marad, a csapat ... a 10 perces célját.'::text,'túlszárnyalja'::text,'túlszárnyalná'::text,'túlszárnyalta'::text,'Ha a sodrás ilyen erős marad, a csapat túlszárnyalja a 10 perces célját.'::text),
(362883,40321,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, ich geh nicht in die Nähe von diesem Kiefer, und mein Tauchbuddy ...'::text,'auch nicht'::text,'auch'::text,'auch nicht'::text,'Nee, ich geh nicht in die Nähe von diesem Kiefer, und mein Tauchbuddy auch nicht.'::text),
(362887,40321,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не-а, я до тієї щелепи не підійду, і мій напарник з дайвінгу ...'::text,'теж ні'::text,'теж'::text,'теж ні'::text,'Не-а, я до тієї щелепи не підійду, і мій напарник з дайвінгу теж ні.'::text),
(362886,40321,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, yo no me acerco a esa mandíbula, y mi compañero de buceo ...'::text,'tampoco'::text,'también'::text,'tampoco'::text,'Qué va, yo no me acerco a esa mandíbula, y mi compañero de buceo tampoco.'::text),
(362885,40321,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non, moi je m''approche pas de cette mâchoire, et mon binôme de plongée ...'::text,'non plus'::text,'aussi'::text,'non plus'::text,'Non, moi je m''approche pas de cette mâchoire, et mon binôme de plongée non plus.'::text),
(362888,40321,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, ben o çeneye yaklaşmam, dalış arkadaşım da ...'::text,'yaklaşmaz'::text,'yaklaşır'::text,'yaklaşmaz'::text,'Yok kanka, ben o çeneye yaklaşmam, dalış arkadaşım da yaklaşmaz.'::text),
(362889,40321,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, én nem megyek annak az állkapocsnak a közelébe, és a búvártársam ...'::text,'sem'::text,'is'::text,'sem'::text,'Á, én nem megyek annak az állkapocsnak a közelébe, és a búvártársam sem.'::text),
(362919,40325,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sich der Hai nicht abgewandt hätte, hätte sein Kiefer die Kamera komplett ...!'::text,'zerquetscht'::text,'zerquetschen'::text,'zerquetschte'::text,'Wenn sich der Hai nicht abgewandt hätte, hätte sein Kiefer die Kamera komplett zerquetscht!'::text),
(362923,40325,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби акула не відвернулася, її щелепа ... камеру повністю!'::text,'розчавила б'::text,'розчавить'::text,'розчавила'::text,'Якби акула не відвернулася, її щелепа розчавила б камеру повністю!'::text),
(362922,40325,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si el tiburón no se hubiera apartado, su mandíbula ... la cámara por completo!'::text,'habría aplastado'::text,'aplastará'::text,'aplastó'::text,'¡Si el tiburón no se hubiera apartado, su mandíbula habría aplastado la cámara por completo!'::text),
(362921,40325,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le requin ne s''était pas détourné, sa mâchoire ... complètement la caméra !'::text,'aurait écrasé'::text,'écrasera'::text,'a écrasé'::text,'Si le requin ne s''était pas détourné, sa mâchoire aurait écrasé complètement la caméra !'::text),
(362924,40325,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpekbalığı dönüp gitmeseydi, çenesi kamerayı tamamen ...!'::text,'ezmiş olurdu'::text,'ezecek'::text,'ezdi'::text,'Köpekbalığı dönüp gitmeseydi, çenesi kamerayı tamamen ezmiş olurdu!'::text),
(362925,40325,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a cápa nem fordul el, az állkapcsa teljesen ... a kamerát!'::text,'összezúzta volna'::text,'összezúzza'::text,'összezúzta'::text,'Ha a cápa nem fordul el, az állkapcsa teljesen összezúzta volna a kamerát!'::text),
(358851,39873,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... die Stange fest, als ihn die Gischt traf, also waren seine Hände beschäftigt.'::text,'umklammerte'::text,'umklammerte'::text,'hat umklammert'::text,'Er umklammerte die Stange fest, als ihn die Gischt traf, also waren seine Hände beschäftigt.'::text),
(358855,39873,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... планку міцно, коли його накрили бризки, тож його руки були зайняті.'::text,'стискав'::text,'стиснув'::text,'стиснув'::text,'Він стискав планку міцно, коли його накрили бризки, тож його руки були зайняті.'::text),
(358854,39873,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... la barra con fuerza cuando le dio el agua, así que tenía las manos ocupadas.'::text,'estaba agarrando'::text,'agarró'::text,'ha agarrado'::text,'Él estaba agarrando la barra con fuerza cuando le dio el agua, así que tenía las manos ocupadas.'::text),
(358853,39873,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... la barre fermement quand les embruns l''ont frappé, donc ses mains étaient occupées.'::text,'serrait'::text,'a serré'::text,'a serré'::text,'Il serrait la barre fermement quand les embruns l''ont frappé, donc ses mains étaient occupées.'::text),
(358856,39873,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Serpinti ona çarptığında o, barı sıkıca ..., yani elleri meşguldü.'::text,'tutuyordu'::text,'tuttu'::text,'tuttu'::text,'Serpinti ona çarptığında o, barı sıkıca tutuyordu, yani elleri meşguldü.'::text),
(358857,39873,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő szorosan ... a rudat, amikor eltalálta a permet, szóval a keze foglalt volt.'::text,'markolta'::text,'megmarkolta'::text,'megmarkolta'::text,'Ő szorosan markolta a rudat, amikor eltalálta a permet, szóval a keze foglalt volt.'::text),
(358905,39879,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er umklammerte die Stange fest ... des starken Zugs vom Kite.'::text,'wegen'::text,'trotz'::text,'obwohl'::text,'Er umklammerte die Stange fest wegen des starken Zugs vom Kite.'::text),
(358909,39879,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він міцно стискав планку ... сильну тягу кайта.'::text,'через'::text,'попри'::text,'хоча'::text,'Він міцно стискав планку через сильну тягу кайта.'::text),
(358908,39879,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él agarraba la barra con fuerza ... el fuerte tirón de la cometa.'::text,'debido a'::text,'a pesar de'::text,'aunque'::text,'Él agarraba la barra con fuerza debido a el fuerte tirón de la cometa.'::text),
(358907,39879,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il serrait fort la barre ... la forte traction du kite.'::text,'à cause de'::text,'malgré'::text,'bien que'::text,'Il serrait fort la barre à cause de la forte traction du kite.'::text),
(358910,39879,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, uçurtmanın güçlü ... barı sıkıca tuttu.'::text,'çekişi yüzünden'::text,'çekişine rağmen'::text,'çekişi olsa da'::text,'O, uçurtmanın güçlü çekişi yüzünden barı sıkıca tuttu.'::text),
(358911,39879,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő erősen markolta a rudat a sárkány erős húzása ...'::text,'miatt'::text,'ellenére'::text,'bár'::text,'Ő erősen markolta a rudat a sárkány erős húzása miatt.'::text),
(380028,42226,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er schaute nach unten und wartete darauf, dass die Gurte ihn ...'::text,'loslassen'::text,'loslassen'::text,'loslassen'::text,'Er schaute nach unten und wartete darauf, dass die Gurte ihn loslassen.'::text),
(380032,42226,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він подивився вниз і чекав, поки ремені його ...'::text,'відпустять'::text,'відпускання'::text,'відпустять'::text,'Він подивився вниз і чекав, поки ремені його відпустять.'::text),
(380031,42226,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él miró hacia abajo y esperó a que las correas lo ...'::text,'soltaran'::text,'soltaran'::text,'soltaran'::text,'Él miró hacia abajo y esperó a que las correas lo soltaran.'::text),
(380030,42226,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a regardé en bas et a attendu que les sangles le ...'::text,'lâchent'::text,'lâchent'::text,'lâchent'::text,'Il a regardé en bas et a attendu que les sangles le lâchent.'::text),
(380033,42226,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O aşağı baktı ve kayışların kendisini ... bekledi.'::text,'bırakmasını'::text,'bırakmasını'::text,'bırakmasını'::text,'O aşağı baktı ve kayışların kendisini bırakmasını bekledi.'::text),
(380034,42226,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő lenézett, és várta, hogy a hevederek ...'::text,'elengedjék'::text,'elengedjék'::text,'elengedjék'::text,'Ő lenézett, és várta, hogy a hevederek elengedjék.'::text),
(380046,42228,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als die Gurte ihn losließen, ... er schon lange auf die Wolken hinunter.'::text,'schaute'::text,'schaut'::text,'schaut'::text,'Als die Gurte ihn losließen, schaute er schon lange auf die Wolken hinunter.'::text),
(380050,42228,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли ремені його відпустили, він уже довго ... вниз на хмари.'::text,'дивився'::text,'дивиться'::text,'дивиться'::text,'Коли ремені його відпустили, він уже довго дивився вниз на хмари.'::text),
(380049,42228,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando las correas lo soltaron, él ya ... un buen rato mirando las nubes.'::text,'llevaba'::text,'lleva'::text,'está'::text,'Cuando las correas lo soltaron, él ya llevaba un buen rato mirando las nubes.'::text),
(380048,42228,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand les sangles l''ont lâché, il ... les nuages en bas depuis longtemps.'::text,'regardait'::text,'regarde'::text,'regarde'::text,'Quand les sangles l''ont lâché, il regardait les nuages en bas depuis longtemps.'::text),
(380051,42228,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kayışlar onu bıraktığında o, uzun süredir aşağıdaki bulutlara ...'::text,'bakıyordu'::text,'bakıyor'::text,'bakıyor'::text,'Kayışlar onu bıraktığında o, uzun süredir aşağıdaki bulutlara bakıyordu.'::text),
(380052,42228,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amikor a hevederek elengedték, ő már sokáig ... le a felhőkre.'::text,'nézett'::text,'néz'::text,'néz'::text,'Amikor a hevederek elengedték, ő már sokáig nézett le a felhőkre.'::text),
(375177,41687,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Mast entfernt wird, ... der Schwarm sein Nest.'::text,'verliert'::text,'verlöre'::text,'verlor'::text,'Wenn der Mast entfernt wird, verliert der Schwarm sein Nest.'::text),
(375181,41687,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо стовп приберуть, зграя ... своє гніздо.'::text,'втратить'::text,'втратила б'::text,'втратила'::text,'Якщо стовп приберуть, зграя втратить своє гніздо.'::text),
(375180,41687,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si se retira el poste, la bandada ... su nido.'::text,'perderá'::text,'perdería'::text,'perdió'::text,'Si se retira el poste, la bandada perderá su nido.'::text),
(375179,41687,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le poteau est retiré, la colonie ... son nid.'::text,'perdra'::text,'perdrait'::text,'a perdu'::text,'Si le poteau est retiré, la colonie perdra son nid.'::text),
(375182,41687,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Direk kaldırılırsa, sürü yuvasını ...'::text,'kaybedecek'::text,'kaybederdi'::text,'kaybetti'::text,'Direk kaldırılırsa, sürü yuvasını kaybedecek.'::text),
(375183,41687,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az oszlopot eltávolítják, a madárcsapat ... a fészkét.'::text,'elveszíti'::text,'elveszítené'::text,'elveszítette'::text,'Ha az oszlopot eltávolítják, a madárcsapat elveszíti a fészkét.'::text),
(375231,41693,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oben auf diesem Mast war das Nest ...! Ein totaler Albtraum!'::text,'komplettes Chaos'::text,'ein komplettes Chaos'::text,'die kompletten Chaos'::text,'Oben auf diesem Mast war das Nest komplettes Chaos! Ein totaler Albtraum!'::text),
(375235,41693,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Нагорі на тому стовпі гніздо було ...! Повний жах!'::text,'повним хаосом'::text,'повним хаосом'::text,'повними хаосами'::text,'Нагорі на тому стовпі гніздо було повним хаосом! Повний жах!'::text),
(375234,41693,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Allá arriba en ese poste, el nido era ...! ¡Una pesadilla total!'::text,'caos total'::text,'un caos total'::text,'los caos totales'::text,'¡Allá arriba en ese poste, el nido era caos total! ¡Una pesadilla total!'::text),
(375233,41693,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Là-haut sur ce poteau, le nid était ... ! Un vrai cauchemar !'::text,'le chaos total'::text,'un chaos total'::text,'les chaos totaux'::text,'Là-haut sur ce poteau, le nid était le chaos total ! Un vrai cauchemar !'::text),
(375236,41693,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O direğin tepesinde yuva ...! Tam bir kâbus!'::text,'tam kaos'::text,'tam bir kaos'::text,'tam kaoslar'::text,'O direğin tepesinde yuva tam kaos! Tam bir kâbus!'::text),
(375237,41693,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fent azon az oszlopon a fészek ... volt! Totális rémálom!'::text,'teljes káosz'::text,'egy teljes káosz'::text,'a teljes káoszok'::text,'Fent azon az oszlopon a fészek teljes káosz volt! Totális rémálom!'::text),
(347673,38631,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Kamera ... mit roter Erde, als das Bike landete. Sie ist komplett hinüber!'::text,'wurde bedeckt'::text,'bedeckte'::text,'ist bedeckt'::text,'Die Kamera wurde bedeckt mit roter Erde, als das Bike landete. Sie ist komplett hinüber!'::text),
(347677,38631,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Камера ... червоною землею, коли мотоцикл приземлився. Вона повністю зіпсована!'::text,'була вкрита'::text,'вкрила'::text,'вкрита'::text,'Камера була вкрита червоною землею, коли мотоцикл приземлився. Вона повністю зіпсована!'::text),
(347676,38631,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cámara ... de tierra roja cuando la moto aterrizó. ¡Está completamente destrozada!'::text,'quedó cubierta'::text,'cubrió'::text,'está cubierta'::text,'La cámara quedó cubierta de tierra roja cuando la moto aterrizó. ¡Está completamente destrozada!'::text),
(347675,38631,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La caméra ... de terre rouge quand la moto a atterri. Elle est complètement fichue !'::text,'a été couverte'::text,'a couvert'::text,'est couverte'::text,'La caméra a été couverte de terre rouge quand la moto a atterri. Elle est complètement fichue !'::text),
(347678,38631,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Motor yere indiğinde kamera kırmızı toprakla ...; tamamen mahvoldu!'::text,'kaplandı'::text,'kapladı'::text,'kaplanıyor'::text,'Motor yere indiğinde kamera kırmızı toprakla kaplandı; tamamen mahvoldu!'::text),
(347679,38631,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kamera ... vörös földdel, amikor a motor landolt. Teljesen tönkrement!'::text,'be lett borítva'::text,'beborított'::text,'be van borítva'::text,'A kamera be lett borítva vörös földdel, amikor a motor landolt. Teljesen tönkrement!'::text),
(347691,38633,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein durchdrehender Hinterreifen schleudert typischerweise ... hinter dem Bike in die Luft.'::text,'lockere Erde'::text,'eine lockere Erde'::text,'die lockeren Erden'::text,'Ein durchdrehender Hinterreifen schleudert typischerweise lockere Erde hinter dem Bike in die Luft.'::text),
(347695,38633,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Колесо, що буксує, зазвичай викидає ... в повітря позаду мотоцикла.'::text,'пухку землю'::text,'пухку землю'::text,'пухкі землі'::text,'Колесо, що буксує, зазвичай викидає пухку землю в повітря позаду мотоцикла.'::text),
(347694,38633,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un neumático trasero que patina suele lanzar ... al aire detrás de la moto.'::text,'tierra suelta'::text,'una tierra suelta'::text,'las tierras sueltas'::text,'Un neumático trasero que patina suele lanzar tierra suelta al aire detrás de la moto.'::text),
(347693,38633,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un pneu arrière qui patine projette généralement ... en l''air derrière la moto.'::text,'de la terre meuble'::text,'une terre meuble'::text,'les terres meubles'::text,'Un pneu arrière qui patine projette généralement de la terre meuble en l''air derrière la moto.'::text),
(347696,38633,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Patinaj yapan bir arka lastik genellikle motorun arkasında havaya ... fırlatır.'::text,'gevşek toprak'::text,'bir gevşek toprak'::text,'gevşek topraklar'::text,'Patinaj yapan bir arka lastik genellikle motorun arkasında havaya gevşek toprak fırlatır.'::text),
(347697,38633,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy kipörgő hátsó gumi jellemzően ... repít a levegőbe a motor mögött.'::text,'laza földet'::text,'egy laza földet'::text,'a laza földeket'::text,'Egy kipörgő hátsó gumi jellemzően laza földet repít a levegőbe a motor mögött.'::text),
(369030,41004,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jeden Abend in jenem Sommer ... der See die Bäume, bis jemand reinsprang.'::text,'spiegelte'::text,'spiegelte'::text,'war gewohnt zu spiegeln'::text,'Jeden Abend in jenem Sommer spiegelte der See die Bäume, bis jemand reinsprang.'::text),
(369034,41004,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кожного вечора того літа озеро ... дерева, поки хтось не стрибнув у воду.'::text,'віддзеркалювало'::text,'віддзеркалювало'::text,'звикло віддзеркалювати'::text,'Кожного вечора того літа озеро віддзеркалювало дерева, поки хтось не стрибнув у воду.'::text),
(369033,41004,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cada tarde de aquel verano, el lago ... los árboles hasta que alguien se tiraba al agua.'::text,'reflejaba'::text,'solía reflejar'::text,'estaba acostumbrado a reflejar'::text,'Cada tarde de aquel verano, el lago reflejaba los árboles hasta que alguien se tiraba al agua.'::text),
(369032,41004,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque soir cet été-là, le lac ... les arbres jusqu''à ce que quelqu''un saute dedans.'::text,'reflétait'::text,'reflétait'::text,'avait l''habitude de refléter'::text,'Chaque soir cet été-là, le lac reflétait les arbres jusqu''à ce que quelqu''un saute dedans.'::text),
(369035,41004,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O yaz her akşam göl, biri suya atlayana kadar ağaçları ...'::text,'yansıtırdı'::text,'yansıtırdı'::text,'yansıtmaya alışkındı'::text,'O yaz her akşam göl, biri suya atlayana kadar ağaçları yansıtırdı.'::text),
(369036,41004,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azon a nyáron minden este a tó ... a fákat, amíg valaki bele nem ugrott.'::text,'tükrözte'::text,'tükrözte'::text,'hozzá volt szokva tükrözni'::text,'Azon a nyáron minden este a tó tükrözte a fákat, amíg valaki bele nem ugrott.'::text),
(369075,41009,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der See ... seit Stunden den Himmel, und jetzt springt er rein. Super gemacht.'::text,'spiegelt'::text,'spiegelt'::text,'spiegelt'::text,'Der See spiegelt seit Stunden den Himmel, und jetzt springt er rein. Super gemacht.'::text),
(369079,41009,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Озеро ... небо вже кілька годин, а тепер він стрибає. Чудова робота.'::text,'віддзеркалює'::text,'віддзеркалює'::text,'віддзеркалює'::text,'Озеро віддзеркалює небо вже кілька годин, а тепер він стрибає. Чудова робота.'::text),
(369078,41009,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El lago ... el cielo durante horas, y ahora él se tira. Buen trabajo.'::text,'ha estado reflejando'::text,'está reflejando'::text,'refleja'::text,'El lago ha estado reflejando el cielo durante horas, y ahora él se tira. Buen trabajo.'::text),
(369077,41009,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le lac ... le ciel depuis des heures, et là il saute dedans. Bravo.'::text,'reflète'::text,'reflète'::text,'reflète'::text,'Le lac reflète le ciel depuis des heures, et là il saute dedans. Bravo.'::text),
(369080,41009,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Göl saatlerdir gökyüzünü ... ve şimdi o suya atlıyor. Harika iş.'::text,'yansıtıyor'::text,'yansıtıyor'::text,'yansıtır'::text,'Göl saatlerdir gökyüzünü yansıtıyor ve şimdi o suya atlıyor. Harika iş.'::text),
(369081,41009,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tó órák óta ... az eget, és most ő beleugrik. Szép munka.'::text,'tükrözi'::text,'tükrözi'::text,'tükrözi'::text,'A tó órák óta tükrözi az eget, és most ő beleugrik. Szép munka.'::text),
(393186,43688,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, ich hab gehört, sie ... diesen Tigerhai über den ganzen Rücken.'::text,'streichelte'::text,'wurde gestreichelt'::text,'streichelnd'::text,'Hör mal, ich hab gehört, sie streichelte diesen Tigerhai über den ganzen Rücken.'::text),
(393190,43688,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що вона ... ту тигрову акулу по всій спині.'::text,'погладила'::text,'була погладжена'::text,'гладячи'::text,'Слухай, я чула, що вона погладила ту тигрову акулу по всій спині.'::text),
(393189,43688,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, yo oí que ella ... a ese tiburón tigre por todo el lomo.'::text,'acarició'::text,'fue acariciada'::text,'acariciando'::text,'Oye, yo oí que ella acarició a ese tiburón tigre por todo el lomo.'::text),
(393188,43688,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu dire qu''elle ... ce requin-tigre sur tout le dos.'::text,'a caressé'::text,'a été caressée'::text,'caressant'::text,'Écoute, j''ai entendu dire qu''elle a caressé ce requin-tigre sur tout le dos.'::text),
(393191,43688,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, ben duydum ki o, kaplan köpekbalığını bütün sırtı boyunca ...'::text,'okşamış'::text,'okşanmış'::text,'okşayarak'::text,'Dinle, ben duydum ki o, kaplan köpekbalığını bütün sırtı boyunca okşamış.'::text),
(393192,43688,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, én úgy hallottam, hogy ő ... azt a tigriscápát végig a hátán.'::text,'megsimogatta'::text,'meg lett simogatva'::text,'simogatva'::text,'Figyelj, én úgy hallottam, hogy ő megsimogatta azt a tigriscápát végig a hátán.'::text),
(381783,42421,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Küken hat mit seiner Angel keinen Fisch gefangen, und ...'::text,'die Meerjungfrau auch nicht'::text,'die Meerjungfrau auch'::text,'die Meerjungfrau auch nicht'::text,'Das Küken hat mit seiner Angel keinen Fisch gefangen, und die Meerjungfrau auch nicht.'::text),
(381787,42421,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Курча не впіймало своєю вудкою жодної риби, і ...'::text,'русалка теж ні'::text,'русалка теж'::text,'русалка теж ні'::text,'Курча не впіймало своєю вудкою жодної риби, і русалка теж ні.'::text),
(381786,42421,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pollito no pescó ningún pez con su caña, y ...'::text,'la sirena tampoco'::text,'la sirena también'::text,'la sirena tampoco'::text,'El pollito no pescó ningún pez con su caña, y la sirena tampoco.'::text),
(381785,42421,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le poussin n''a attrapé aucun poisson avec sa canne, et ...'::text,'la sirène non plus'::text,'la sirène aussi'::text,'la sirène non plus'::text,'Le poussin n''a attrapé aucun poisson avec sa canne, et la sirène non plus.'::text),
(381788,42421,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Civciv oltasıyla hiç balık tutamadı, ve ...'::text,'deniz kızı da tutamadı'::text,'deniz kızı da tuttu'::text,'deniz kızı da tutamadı'::text,'Civciv oltasıyla hiç balık tutamadı, ve deniz kızı da tutamadı.'::text),
(381789,42421,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csibe nem fogott halat a horgászbotjával, és ...'::text,'a sellő sem'::text,'a sellő is'::text,'a sellő sem'::text,'A csibe nem fogott halat a horgászbotjával, és a sellő sem.'::text),
(381801,42423,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, angeblich wird dieses Küken bis heute Abend mit seiner Angel einen Fisch ...'::text,'gefangen haben'::text,'fangen'::text,'am Fangen sein'::text,'Bestie, angeblich wird dieses Küken bis heute Abend mit seiner Angel einen Fisch gefangen haben.'::text),
(381805,42423,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, до вечора те курча ... рибу своєю вудкою.'::text,'впіймає'::text,'впіймає'::text,'ловитиме'::text,'Подруго, кажуть, до вечора те курча впіймає рибу своєю вудкою.'::text),
(381804,42423,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer para esta noche ese pollito ... un pez con su caña.'::text,'habrá pescado'::text,'pescará'::text,'estará pescando'::text,'Amiga, al parecer para esta noche ese pollito habrá pescado un pez con su caña.'::text),
(381803,42423,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, apparemment d''ici ce soir ce poussin ... un poisson avec sa canne.'::text,'aura attrapé'::text,'attrapera'::text,'sera en train d''attraper'::text,'Bestie, apparemment d''ici ce soir ce poussin aura attrapé un poisson avec sa canne.'::text),
(381806,42423,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duyduğuma göre bu akşama kadar o civciv oltasıyla bir balık ...'::text,'tutmuş olacak'::text,'tutacak'::text,'tutuyor olacak'::text,'Kanka, duyduğuma göre bu akşama kadar o civciv oltasıyla bir balık tutmuş olacak.'::text),
(381807,42423,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, állítólag estére az a csibe ... egy halat a botjával.'::text,'ki fog fogni'::text,'kifog'::text,'épp horgászni fog'::text,'Bestie, állítólag estére az a csibe ki fog fogni egy halat a botjával.'::text),
(403257,44807,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis 14:00 Uhr wird laut Zeitplan jeder Fallschirmspringer vom Flügel ...'::text,'gesprungen sein'::text,'springen'::text,'springt'::text,'Bis 14:00 Uhr wird laut Zeitplan jeder Fallschirmspringer vom Flügel gesprungen sein.'::text),
(403261,44807,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До 14:00 кожен парашутист ... з крила, згідно з графіком.'::text,'стрибне'::text,'стрибне'::text,'стрибає'::text,'До 14:00 кожен парашутист стрибне з крила, згідно з графіком.'::text),
(403260,44807,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para las 14:00, todos los paracaidistas ... del ala, según el cronograma.'::text,'habrán saltado'::text,'saltarán'::text,'saltan'::text,'Para las 14:00, todos los paracaidistas habrán saltado del ala, según el cronograma.'::text),
(403259,44807,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici 14 h, chaque parachutiste ... de l''aile, selon le planning.'::text,'aura sauté'::text,'sautera'::text,'saute'::text,'D''ici 14 h, chaque parachutiste aura sauté de l''aile, selon le planning.'::text),
(403262,44807,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zaman çizelgesine göre saat 14:00''e kadar her paraşütçü kanattan ...'::text,'atlamış olacak'::text,'atlayacak'::text,'atlar'::text,'Zaman çizelgesine göre saat 14:00''e kadar her paraşütçü kanattan atlamış olacak.'::text),
(403263,44807,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'14:00-ra az ütemterv szerint minden ejtőernyős ... a szárnyról.'::text,'már leugrott'::text,'le fog ugrani'::text,'ugrik'::text,'14:00-ra az ütemterv szerint minden ejtőernyős már leugrott a szárnyról.'::text),
(365061,40563,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, aber du ... vorhin so smooth von diesem Wrack. Ikonisch.'::text,'sprangst'::text,'sprangst gerade'::text,'bist gesprungen'::text,'Okay, aber du sprangst vorhin so smooth von diesem Wrack. Ikonisch.'::text),
(365065,40563,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ну, але ти так плавно ... з того уламка корабля раніше. Культово.'::text,'стрибнула'::text,'стрибала'::text,'стрибнула'::text,'Ну, але ти так плавно стрибнула з того уламка корабля раніше. Культово.'::text),
(365064,40563,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pero tú ... de ese barco hundido con tanta elegancia antes. Icónico.'::text,'saltaste'::text,'estabas saltando'::text,'has saltado'::text,'Vale, pero tú saltaste de ese barco hundido con tanta elegancia antes. Icónico.'::text),
(365063,40563,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok mais tout à l''heure tu ... de cette épave avec tellement de style. Iconique.'::text,'as sauté'::text,'sautais'::text,'as sauté'::text,'Ok mais tout à l''heure tu as sauté de cette épave avec tellement de style. Iconique.'::text),
(365066,40563,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam ama sen az önce o batığın üstünden öyle zarif ..., ikonik.'::text,'atladın'::text,'atlıyordun'::text,'atladın'::text,'Tamam ama sen az önce o batığın üstünden öyle zarif atladın, ikonik.'::text),
(365067,40563,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, de te korábban olyan lazán ... le arról a roncsról. Ikonikus.'::text,'ugrottál'::text,'ugráltál'::text,'ugrottál'::text,'Oké, de te korábban olyan lazán ugrottál le arról a roncsról. Ikonikus.'::text),
(365124,40570,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie sprang ins Wasser, ... der Tigerhaie, die unter ihr schwammen.'::text,'trotz'::text,'obwohl'::text,'falls'::text,'Sie sprang ins Wasser, trotz der Tigerhaie, die unter ihr schwammen.'::text),
(365128,40570,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона стрибнула у воду ... тигрових акул, що плавали внизу.'::text,'попри'::text,'хоча'::text,'на випадок'::text,'Вона стрибнула у воду попри тигрових акул, що плавали внизу.'::text),
(365127,40570,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella saltó al agua ... los tiburones tigre que nadaban debajo.'::text,'a pesar de'::text,'aunque'::text,'por si'::text,'Ella saltó al agua a pesar de los tiburones tigre que nadaban debajo.'::text),
(365126,40570,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a sauté dans l''eau ... les requins-tigres qui nageaient en dessous.'::text,'malgré'::text,'bien que'::text,'au cas où'::text,'Elle a sauté dans l''eau malgré les requins-tigres qui nageaient en dessous.'::text),
(365129,40570,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, aşağıda yüzen kaplan köpekbalıklarına ... suya atladı.'::text,'rağmen'::text,'gerçi'::text,'diye'::text,'O, aşağıda yüzen kaplan köpekbalıklarına rağmen suya atladı.'::text),
(365130,40570,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő beugrott a vízbe a lent úszó tigriscápák ...'::text,'ellenére'::text,'bár'::text,'esetére'::text,'Ő beugrott a vízbe a lent úszó tigriscápák ellenére.'::text),
(363882,40432,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine Lagune ist Wasser, ... neben einem Strand ist, also hat dieser Strand eine Lagune.'::text,'das'::text,'der'::text,'wo'::text,'Eine Lagune ist Wasser, das neben einem Strand ist, also hat dieser Strand eine Lagune.'::text),
(363886,40432,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лагуна — це вода, ... знаходиться біля пляжу, тож цей пляж має лагуну.'::text,'яка'::text,'хто'::text,'де'::text,'Лагуна — це вода, яка знаходиться біля пляжу, тож цей пляж має лагуну.'::text),
(363885,40432,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una laguna es agua ... está junto a una playa, así que esta playa tiene una laguna.'::text,'que'::text,'quien'::text,'donde'::text,'Una laguna es agua que está junto a una playa, así que esta playa tiene una laguna.'::text),
(363884,40432,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une lagune, c''est de l''eau ... est à côté d''une plage, donc cette plage a une lagune.'::text,'qui'::text,'qui'::text,'où'::text,'Une lagune, c''est de l''eau qui est à côté d''une plage, donc cette plage a une lagune.'::text),
(363887,40432,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lagün, bir plajın yanında ... sudur, yani bu plajın bir lagünü var.'::text,'olan'::text,'kim'::text,'nerede'::text,'Lagün, bir plajın yanında olan sudur, yani bu plajın bir lagünü var.'::text),
(363888,40432,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lagúna olyan víz, ... egy strand mellett van, szóval ennek a strandnak van lagúnája.'::text,'amely'::text,'aki'::text,'ahol'::text,'A lagúna olyan víz, amely egy strand mellett van, szóval ennek a strandnak van lagúnája.'::text),
(363909,40435,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Lagune erstreckt sich bis ... jenseits der Felswände.'::text,'zum offenen Meer'::text,'zu einem offenen Meer'::text,'zu offenem Meer'::text,'Die Lagune erstreckt sich bis zum offenen Meer jenseits der Felswände.'::text),
(363913,40435,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лагуна тягнеться аж до ... за скелястими стінами.'::text,'відкритого моря'::text,'відкритого моря'::text,'відкритого моря'::text,'Лагуна тягнеться аж до відкритого моря за скелястими стінами.'::text),
(363912,40435,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La laguna se extiende hasta ... más allá de las paredes de roca.'::text,'el mar abierto'::text,'un mar abierto'::text,'mar abierto'::text,'La laguna se extiende hasta el mar abierto más allá de las paredes de roca.'::text),
(363911,40435,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le lagon s''étend jusqu''à ... au-delà des parois rocheuses.'::text,'la haute mer'::text,'une haute mer'::text,'haute mer'::text,'Le lagon s''étend jusqu''à la haute mer au-delà des parois rocheuses.'::text),
(363914,40435,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lagün, kaya duvarlarının ötesindeki ... kadar uzanıyor.'::text,'açık denize'::text,'bir açık denize'::text,'açık denize'::text,'Lagün, kaya duvarlarının ötesindeki açık denize kadar uzanıyor.'::text),
(363915,40435,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lagúna a sziklafalakon túl ... nyúlik.'::text,'a nyílt tengerig'::text,'egy nyílt tengerig'::text,'nyílt tengerig'::text,'A lagúna a sziklafalakon túl a nyílt tengerig nyúlik.'::text),
(392241,43583,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Henne ... den Stock quer über den Schnabel der Taube.'::text,'drückte'::text,'wurde gedrückt'::text,'drückend'::text,'Die Henne drückte den Stock quer über den Schnabel der Taube.'::text),
(392245,43583,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Курка ... палицю поперек дзьоба голуба.'::text,'притиснула'::text,'була притиснута'::text,'притискаючи'::text,'Курка притиснула палицю поперек дзьоба голуба.'::text),
(392244,43583,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La gallina ... el palo contra el pico de la paloma.'::text,'apretó'::text,'fue apretada'::text,'apretando'::text,'La gallina apretó el palo contra el pico de la paloma.'::text),
(392243,43583,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La poule ... le bâton en travers du bec du pigeon.'::text,'a pressé'::text,'a été pressée'::text,'pressant'::text,'La poule a pressé le bâton en travers du bec du pigeon.'::text),
(392246,43583,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tavuk sopayı güvercinin gagasına ...'::text,'bastırdı'::text,'bastırıldı'::text,'bastırarak'::text,'Tavuk sopayı güvercinin gagasına bastırdı.'::text),
(392247,43583,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tyúk ... a botot a galamb csőrére.'::text,'rányomta'::text,'rá lett nyomva'::text,'rányomva'::text,'A tyúk rányomta a botot a galamb csőrére.'::text),
(374223,41581,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie erreichte die Kissen, ... sich um und ließ sich darauf fallen. Makellose Landung.'::text,'drehte'::text,'drehte gerade'::text,'hat gedreht'::text,'Sie erreichte die Kissen, drehte sich um und ließ sich darauf fallen. Makellose Landung.'::text),
(374227,41581,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона дісталася подушок, ... і впала на них. Бездоганне приземлення.'::text,'розвернулася'::text,'розверталася'::text,'розвернулася'::text,'Вона дісталася подушок, розвернулася і впала на них. Бездоганне приземлення.'::text),
(374226,41581,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella llegó a las almohadas, ... y se dejó caer sobre ellas. Aterrizaje impecable.'::text,'se giró'::text,'se estaba girando'::text,'se ha girado'::text,'Ella llegó a las almohadas, se giró y se dejó caer sobre ellas. Aterrizaje impecable.'::text),
(374225,41581,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a atteint les oreillers, ... et s''est laissée tomber dessus. Atterrissage parfait.'::text,'s''est retournée'::text,'se retournait'::text,'s''est retournée'::text,'Elle a atteint les oreillers, s''est retournée et s''est laissée tomber dessus. Atterrissage parfait.'::text),
(374228,41581,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O yastıklara ulaştı, ... ve üzerlerine düştü. Kusursuz iniş.'::text,'döndü'::text,'dönüyordu'::text,'döndü'::text,'O yastıklara ulaştı, döndü ve üzerlerine düştü. Kusursuz iniş.'::text),
(374229,41581,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő elérte a párnákat, ... és rájuk vetette magát. Hibátlan landolás.'::text,'megfordult'::text,'éppen fordult'::text,'megfordult'::text,'Ő elérte a párnákat, megfordult és rájuk vetette magát. Hibátlan landolás.'::text),
(374295,41589,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, du ... die Kissen in eine perfekte Reihe gelegt, bevor du aufs Bett gesprungen bist.'::text,'hattest'::text,'hast'::text,'legst'::text,'Respekt, du hattest die Kissen in eine perfekte Reihe gelegt, bevor du aufs Bett gesprungen bist.'::text),
(374299,41589,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект, ти ... подушки в ідеальний ряд, перш ніж стрибнути на ліжко.'::text,'вишикувала'::text,'вишикувала'::text,'шикуєш'::text,'Респект, ти вишикувала подушки в ідеальний ряд, перш ніж стрибнути на ліжко.'::text),
(374298,41589,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto, tú ... las almohadas en una fila perfecta antes de saltar a la cama.'::text,'habías alineado'::text,'has alineado'::text,'alineas'::text,'Respeto, tú habías alineado las almohadas en una fila perfecta antes de saltar a la cama.'::text),
(374297,41589,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect, tu ... les oreillers en une rangée parfaite avant de sauter sur le lit.'::text,'avais aligné'::text,'as aligné'::text,'alignes'::text,'Respect, tu avais aligné les oreillers en une rangée parfaite avant de sauter sur le lit.'::text),
(374300,41589,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saygılar, sen yatağa atlamadan önce yastıkları kusursuz bir sıraya ...'::text,'dizmiştin'::text,'dizdin'::text,'diziyorsun'::text,'Saygılar, sen yatağa atlamadan önce yastıkları kusursuz bir sıraya dizmiştin.'::text),
(374301,41589,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, te tökéletes sorba ... a párnákat, mielőtt ráugrottál az ágyra.'::text,'raktad'::text,'raktad'::text,'rakod'::text,'Respekt, te tökéletes sorba raktad a párnákat, mielőtt ráugrottál az ágyra.'::text),
(383070,42564,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Paddler sagte, das Wasser ... zu schnell an ihm vorbei, um die Felsen zu sehen.'::text,'rausche'::text,'rauscht'::text,'rauschen'::text,'Der Paddler sagte, das Wasser rausche zu schnell an ihm vorbei, um die Felsen zu sehen.'::text),
(383074,42564,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Веслувальник сказав, що вода ... повз нього надто швидко, щоб розгледіти каміння.'::text,'мчала'::text,'мчить'::text,'мчати'::text,'Веслувальник сказав, що вода мчала повз нього надто швидко, щоб розгледіти каміння.'::text),
(383073,42564,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El palista dijo que el agua ... junto a él demasiado rápido para ver las rocas.'::text,'corría'::text,'corre'::text,'correr'::text,'El palista dijo que el agua corría junto a él demasiado rápido para ver las rocas.'::text),
(383072,42564,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le kayakiste a dit que l''eau ... à côté de lui trop vite pour voir les rochers.'::text,'filait'::text,'file'::text,'filer'::text,'Le kayakiste a dit que l''eau filait à côté de lui trop vite pour voir les rochers.'::text),
(383075,42564,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanocu, suyun kayaları göremeyeceği kadar hızlı yanından ... söyledi.'::text,'aktığını'::text,'akıyor'::text,'akmak'::text,'Kanocu, suyun kayaları göremeyeceği kadar hızlı yanından aktığını söyledi.'::text),
(383076,42564,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kajakos azt mondta, hogy a víz túl gyorsan ... el mellette ahhoz, hogy lássa a sziklákat.'::text,'zúdult'::text,'zúdul'::text,'zúdulni'::text,'A kajakos azt mondta, hogy a víz túl gyorsan zúdult el mellette ahhoz, hogy lássa a sziklákat.'::text),
(383124,42570,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Angeblich ... er jeden Sommer diesen Fluss runter, Bestie.'::text,'rast'::text,'rast gerade'::text,'ist gerast'::text,'Angeblich rast er jeden Sommer diesen Fluss runter, Bestie.'::text),
(383128,42570,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, він ... вниз тією річкою щоліта, подруго.'::text,'мчить'::text,'мчить'::text,'мчав'::text,'Кажуть, він мчить вниз тією річкою щоліта, подруго.'::text),
(383127,42570,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Al parecer él ... por ese río cada verano, amiga.'::text,'baja a toda velocidad'::text,'está bajando a toda velocidad'::text,'ha bajado a toda velocidad'::text,'Al parecer él baja a toda velocidad por ese río cada verano, amiga.'::text),
(383126,42570,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Apparemment, il ... cette rivière chaque été, ma belle.'::text,'dévale'::text,'est en train de dévaler'::text,'a dévalé'::text,'Apparemment, il dévale cette rivière chaque été, ma belle.'::text),
(383129,42570,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Duyduğuma göre o her yaz o nehirden hızla ..., kanka.'::text,'iniyor'::text,'iniyor'::text,'indi'::text,'Duyduğuma göre o her yaz o nehirden hızla iniyor, kanka.'::text),
(383130,42570,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Állítólag ő minden nyáron ... azon a folyón, bestie.'::text,'lesüvít'::text,'épp lesüvít'::text,'lesüvített'::text,'Állítólag ő minden nyáron lesüvít azon a folyón, bestie.'::text),
(403869,44875,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... schon seit fünf Minuten nach einem Haargummi, und an ihrem Handgelenk sind drei.'::text,'sucht'::text,'sucht'::text,'sucht'::text,'Sie sucht schon seit fünf Minuten nach einem Haargummi, und an ihrem Handgelenk sind drei.'::text),
(403873,44875,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона вже п''ять хвилин ... гумку для волосся, а на зап''ясті в неї три.'::text,'шукає'::text,'шукає'::text,'шукає'::text,'Вона вже п''ять хвилин шукає гумку для волосся, а на зап''ясті в неї три.'::text),
(403872,44875,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... una goma del pelo desde hace cinco minutos, y tiene tres en la muñeca.'::text,'ha estado buscando'::text,'está buscando'::text,'busca'::text,'Ella ha estado buscando una goma del pelo desde hace cinco minutos, y tiene tres en la muñeca.'::text),
(403871,44875,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... un élastique depuis cinq minutes, et elle en a trois au poignet.'::text,'cherche'::text,'cherche'::text,'cherche'::text,'Elle cherche un élastique depuis cinq minutes, et elle en a trois au poignet.'::text),
(403874,44875,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O beş dakikadır bir saç tokası ... ve bileğinde üç tane var.'::text,'arıyor'::text,'arıyor'::text,'arar'::text,'O beş dakikadır bir saç tokası arıyor ve bileğinde üç tane var.'::text),
(403875,44875,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő már öt perce ... egy hajgumit, és három van a csuklóján.'::text,'keres'::text,'keres'::text,'keres'::text,'Ő már öt perce keres egy hajgumit, és három van a csuklóján.'::text),
(403941,44883,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie durchsuchte das ganze Zimmer, ... die Haargummis die ganze Zeit an ihrem Handgelenk waren.'::text,'obwohl'::text,'trotz'::text,'wegen'::text,'Sie durchsuchte das ganze Zimmer, obwohl die Haargummis die ganze Zeit an ihrem Handgelenk waren.'::text),
(403945,44883,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона обшукала всю кімнату, ... гумки весь час були в неї на зап''ясті.'::text,'хоча'::text,'попри'::text,'через'::text,'Вона обшукала всю кімнату, хоча гумки весь час були в неї на зап''ясті.'::text),
(403944,44883,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella buscó por toda la habitación, ... las gomas estaban en su muñeca todo el tiempo.'::text,'aunque'::text,'a pesar de'::text,'debido a'::text,'Ella buscó por toda la habitación, aunque las gomas estaban en su muñeca todo el tiempo.'::text),
(403943,44883,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a fouillé toute la chambre, ... les élastiques étaient à son poignet depuis le début.'::text,'alors que'::text,'malgré'::text,'en raison de'::text,'Elle a fouillé toute la chambre, alors que les élastiques étaient à son poignet depuis le début.'::text),
(403946,44883,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O bütün odayı aradı, ... tokalar başından beri bileğindeydi.'::text,'oysa'::text,'rağmen'::text,'sayesinde'::text,'O bütün odayı aradı, oysa tokalar başından beri bileğindeydi.'::text),
(403947,44883,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő átkutatta az egész szobát, ... a hajgumik végig a csuklóján voltak.'::text,'pedig'::text,'annak ellenére'::text,'miatt'::text,'Ő átkutatta az egész szobát, pedig a hajgumik végig a csuklóján voltak.'::text),
(373476,41498,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Gipfel ist oben, weil er hoch ist, und der Hubschrauber ...'::text,'auch'::text,'auch'::text,'auch nicht'::text,'Der Gipfel ist oben, weil er hoch ist, und der Hubschrauber auch.'::text),
(373480,41498,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вершина нагорі, бо вона висока, і гелікоптер ...'::text,'теж'::text,'теж'::text,'теж ні'::text,'Вершина нагорі, бо вона висока, і гелікоптер теж.'::text),
(373479,41498,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pico está arriba porque es alto, y ... el helicóptero.'::text,'también lo está'::text,'también lo hace'::text,'tampoco lo está'::text,'El pico está arriba porque es alto, y también lo está el helicóptero.'::text),
(373478,41498,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le sommet est en haut parce qu''il est haut, et l''hélicoptère ...'::text,'aussi'::text,'aussi'::text,'non plus'::text,'Le sommet est en haut parce qu''il est haut, et l''hélicoptère aussi.'::text),
(373481,41498,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zirve yukarıda çünkü yüksek, ve helikopter de ...'::text,'öyle'::text,'öyle'::text,'öyle değil'::text,'Zirve yukarıda çünkü yüksek, ve helikopter de öyle.'::text),
(373482,41498,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csúcs fent van, mert magas, és a helikopter ...'::text,'is'::text,'is'::text,'sem'::text,'A csúcs fent van, mert magas, és a helikopter is.'::text),
(400044,44450,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, sie hat mir erzählt, dass sie vorher noch nie kopfüber an einem Flugzeug ...'::text,'gehangen hatte'::text,'gehangen hat'::text,'hängt'::text,'Bestie, sie hat mir erzählt, dass sie vorher noch nie kopfüber an einem Flugzeug gehangen hatte.'::text),
(400048,44450,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона сказала мені, що ніколи раніше не ... догори ногами з літака.'::text,'висіла'::text,'висіла'::text,'висить'::text,'Подруго, вона сказала мені, що ніколи раніше не висіла догори ногами з літака.'::text),
(400047,44450,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, ella me dijo que nunca antes ... boca abajo de un avión.'::text,'había colgado'::text,'ha colgado'::text,'cuelga'::text,'Amiga, ella me dijo que nunca antes había colgado boca abajo de un avión.'::text),
(400046,44450,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, elle m''a dit qu''avant, elle ... la tête en bas sous un avion.'::text,'n''avait jamais été suspendue'::text,'n''a jamais été suspendue'::text,'n''est jamais suspendue'::text,'Ma belle, elle m''a dit qu''avant, elle n''avait jamais été suspendue la tête en bas sous un avion.'::text),
(400049,44450,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o bana daha önce hiç uçaktan baş aşağı ... söyledi.'::text,'asılmadığını'::text,'asılmadığını'::text,'asılmıyor'::text,'Kanka, o bana daha önce hiç uçaktan baş aşağı asılmadığını söyledi.'::text),
(400050,44450,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, ő azt mondta nekem, hogy korábban még soha nem ... fejjel lefelé egy repülőről.'::text,'lógott'::text,'lógott'::text,'lóg'::text,'Bestie, ő azt mondta nekem, hogy korábban még soha nem lógott fejjel lefelé egy repülőről.'::text),
(334920,37214,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Am nächsten Morgen sagte die schlafende Person, eine Mücke habe sie in der Nacht ...'::text,'gestochen'::text,'gestochen'::text,'steche'::text,'Am nächsten Morgen sagte die schlafende Person, eine Mücke habe sie in der Nacht gestochen.'::text),
(334924,37214,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Наступного ранку сплюх сказав, що вночі його ... комар.'::text,'вкусив'::text,'вкусив'::text,'кусає'::text,'Наступного ранку сплюх сказав, що вночі його вкусив комар.'::text),
(334923,37214,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A la mañana siguiente, la persona dormida dijo que un mosquito le ... por la noche.'::text,'había picado'::text,'ha picado'::text,'pica'::text,'A la mañana siguiente, la persona dormida dijo que un mosquito le había picado por la noche.'::text),
(334922,37214,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le lendemain matin, la personne endormie a dit qu''un moustique ... pendant la nuit.'::text,'l''avait piquée'::text,'l''a piquée'::text,'la pique'::text,'Le lendemain matin, la personne endormie a dit qu''un moustique l''avait piquée pendant la nuit.'::text),
(334925,37214,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ertesi sabah uyuyan kişi, gece bir sivrisineğin onu ... söyledi.'::text,'ısırdığını'::text,'ısırdığını'::text,'ısırıyor'::text,'Ertesi sabah uyuyan kişi, gece bir sivrisineğin onu ısırdığını söyledi.'::text),
(334926,37214,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Másnap reggel az alvó azt mondta, hogy éjjel ... egy szúnyog.'::text,'megcsípte'::text,'megcsípte'::text,'csípi'::text,'Másnap reggel az alvó azt mondta, hogy éjjel megcsípte egy szúnyog.'::text),
(334956,37218,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Smooth: Als die schlafende Person den Stich spürte, warst du schon ...'::text,'weggeflogen'::text,'weggeflogen'::text,'weggeflogen'::text,'Smooth: Als die schlafende Person den Stich spürte, warst du schon weggeflogen.'::text),
(334960,37218,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Спритно: поки сплюх відчув укус, ти вже ...'::text,'відлетів'::text,'відлетів'::text,'відлетів'::text,'Спритно: поки сплюх відчув укус, ти вже відлетів.'::text),
(334959,37218,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué fino: cuando la persona dormida sintió la picadura, tú ya te ...'::text,'habías ido volando'::text,'has ido volando'::text,'fuiste volando'::text,'Qué fino: cuando la persona dormida sintió la picadura, tú ya te habías ido volando.'::text),
(334958,37218,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Stylé : quand la personne endormie a senti la piqûre, tu t''étais déjà ...'::text,'envolé'::text,'envolé'::text,'envolé'::text,'Stylé : quand la personne endormie a senti la piqûre, tu t''étais déjà envolé.'::text),
(334961,37218,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok şık: uyuyan kişi ısırığı hissettiğinde sen çoktan ...'::text,'uçup gitmiştin'::text,'uçup gittin'::text,'uçup gittin'::text,'Çok şık: uyuyan kişi ısırığı hissettiğinde sen çoktan uçup gitmiştin.'::text),
(334962,37218,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ügyes: mire az alvó megérezte a csípést, te már ...'::text,'elrepültél'::text,'elrepültél'::text,'elrepültél'::text,'Ügyes: mire az alvó megérezte a csípést, te már elrepültél.'::text),
(381315,42369,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... die nächste Rakete von dieser Rampe auf, und alles wird beben!'::text,'steigt'::text,'steigt'::text,'steigt'::text,'Morgen um diese Zeit steigt die nächste Rakete von dieser Rampe auf, und alles wird beben!'::text),
(381319,42369,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час наступна ракета ... з цього майданчика, і все трястиметься!'::text,'здійматиметься'::text,'злетить'::text,'здіймається'::text,'Завтра в цей час наступна ракета здійматиметься з цього майданчика, і все трястиметься!'::text),
(381318,42369,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Mañana a esta hora, el próximo cohete ... desde esta plataforma, y todo temblará!'::text,'estará despegando'::text,'despegará'::text,'despega'::text,'¡Mañana a esta hora, el próximo cohete estará despegando desde esta plataforma, y todo temblará!'::text),
(381317,42369,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à cette heure-ci, la prochaine fusée ... de ce pas de tir, et tout va trembler !'::text,'sera en train de s''élever'::text,'s''élèvera'::text,'s''élève'::text,'Demain à cette heure-ci, la prochaine fusée sera en train de s''élever de ce pas de tir, et tout va trembler !'::text),
(381320,42369,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte bir sonraki roket bu rampadan ... ve her şey sallanacak!'::text,'yükseliyor olacak'::text,'yükselecek'::text,'yükselir'::text,'Yarın bu saatte bir sonraki roket bu rampadan yükseliyor olacak ve her şey sallanacak!'::text),
(381321,42369,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor a következő rakéta ... erről az indítóállásról, és minden rázkódni fog!'::text,'épp emelkedik'::text,'emelkedik majd'::text,'emelkedik'::text,'Holnap ilyenkor a következő rakéta épp emelkedik erről az indítóállásról, és minden rázkódni fog!'::text),
(381360,42374,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Um 09:01 Uhr ... die Rakete laut Zeitplan schon am Turm vorbei aufgestiegen.'::text,'war'::text,'stieg'::text,'stieg gerade'::text,'Um 09:01 Uhr war die Rakete laut Zeitplan schon am Turm vorbei aufgestiegen.'::text),
(381364,42374,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До 09:01 ракета ... повз вежу, згідно з графіком.'::text,'піднялася'::text,'піднялася'::text,'піднімалася'::text,'До 09:01 ракета піднялася повз вежу, згідно з графіком.'::text),
(381363,42374,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para las 09:01, el cohete ya ... por delante de la torre, según el cronograma.'::text,'había subido'::text,'subió'::text,'estaba subiendo'::text,'Para las 09:01, el cohete ya había subido por delante de la torre, según el cronograma.'::text),
(381362,42374,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À 9 h 01, la fusée ... au-delà de la tour, selon le planning.'::text,'s''était élevée'::text,'s''est élevée'::text,'s''élevait'::text,'À 9 h 01, la fusée s''était élevée au-delà de la tour, selon le planning.'::text),
(381365,42374,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zaman çizelgesine göre saat 09:01''de roket kulenin yanından ...'::text,'yükselmişti'::text,'yükseldi'::text,'yükseliyordu'::text,'Zaman çizelgesine göre saat 09:01''de roket kulenin yanından yükselmişti.'::text),
(381366,42374,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'09:01-re a rakéta az ütemterv szerint már ... a torony mellett.'::text,'felemelkedett'::text,'emelkedett'::text,'éppen emelkedett'::text,'09:01-re a rakéta az ütemterv szerint már felemelkedett a torony mellett.'::text),
(343911,38213,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, die Stelle, ... du deinen Tee gegossen hast, ist zu einem perfekten Stern gesprungen.'::text,'wo'::text,'die'::text,'wer'::text,'Ehrlich, die Stelle, wo du deinen Tee gegossen hast, ist zu einem perfekten Stern gesprungen.'::text),
(343915,38213,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, місце, ... ти вилила чай, тріснуло ідеальною зіркою.'::text,'де'::text,'яке'::text,'хто'::text,'Чесно, місце, де ти вилила чай, тріснуло ідеальною зіркою.'::text),
(343914,38213,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, el sitio ... echaste tu té se agrietó formando una estrella perfecta.'::text,'donde'::text,'que'::text,'quien'::text,'Sinceramente, el sitio donde echaste tu té se agrietó formando una estrella perfecta.'::text),
(343913,38213,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, l''endroit ... tu as versé ton thé s''est fissuré en une étoile parfaite.'::text,'où'::text,'que'::text,'qui'::text,'Franchement, l''endroit où tu as versé ton thé s''est fissuré en une étoile parfaite.'::text),
(343916,38213,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, çayını ... yer mükemmel bir yıldız şeklinde çatladı.'::text,'döktüğün'::text,'döktüğün'::text,'döken'::text,'Açıkçası, çayını döktüğün yer mükemmel bir yıldız şeklinde çatladı.'::text),
(343917,38213,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, az a hely, ... kiöntötted a teádat, tökéletes csillag alakban megrepedt.'::text,'ahol'::text,'amely'::text,'aki'::text,'Őszintén, az a hely, ahol kiöntötted a teádat, tökéletes csillag alakban megrepedt.'::text),
(382323,42481,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tatsächlich ... frühe Astronomen zu glauben, dass der runde Mond vollkommen glatt sei.'::text,'pflegten'::text,'pflegten'::text,'waren gewohnt'::text,'Tatsächlich pflegten frühe Astronomen zu glauben, dass der runde Mond vollkommen glatt sei.'::text),
(382327,42481,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Насправді ранні астрономи ... вважати, що кругла Луна ідеально гладка.'::text,'мали звичку'::text,'мали звичку'::text,'були звиклі'::text,'Насправді ранні астрономи мали звичку вважати, що кругла Луна ідеально гладка.'::text),
(382326,42481,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De hecho, los primeros astrónomos ... creer que la luna redonda era perfectamente lisa.'::text,'solían'::text,'solían'::text,'estaban acostumbrados a'::text,'De hecho, los primeros astrónomos solían creer que la luna redonda era perfectamente lisa.'::text),
(382325,42481,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En fait, les premiers astronomes ... que la lune ronde était parfaitement lisse.'::text,'croyaient'::text,'croyaient'::text,'étaient habitués à croire'::text,'En fait, les premiers astronomes croyaient que la lune ronde était parfaitement lisse.'::text),
(382328,42481,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aslında ilk gökbilimciler yuvarlak Ay''ın tamamen pürüzsüz olduğuna ...'::text,'inanırlardı'::text,'inanırlardı'::text,'inanmaya alışkındı'::text,'Aslında ilk gökbilimciler yuvarlak Ay''ın tamamen pürüzsüz olduğuna inanırlardı.'::text),
(382329,42481,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Valójában a korai csillagászok úgy ..., hogy a kerek Hold tökéletesen sima.'::text,'hitték'::text,'hitték'::text,'voltak hozzászokva'::text,'Valójában a korai csillagászok úgy hitték, hogy a kerek Hold tökéletesen sima.'::text),
(402096,44678,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Kühe früher Platz gemacht hätten, ... er schon unterwegs. Eine entspannte Fahrt, offensichtlich.'::text,'wäre'::text,'wäre gewesen'::text,'wird sein'::text,'Wenn die Kühe früher Platz gemacht hätten, wäre er schon unterwegs. Eine entspannte Fahrt, offensichtlich.'::text),
(402100,44678,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби корови відійшли раніше, він уже ... в дорозі. Спокійна поїздка, очевидно.'::text,'був би'::text,'був би'::text,'буде'::text,'Якби корови відійшли раніше, він уже був би в дорозі. Спокійна поїздка, очевидно.'::text),
(402099,44678,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si las vacas se hubieran apartado antes, él ya ... de camino. Un paseo tranquilo, obviamente.'::text,'estaría'::text,'habría estado'::text,'estará'::text,'Si las vacas se hubieran apartado antes, él ya estaría de camino. Un paseo tranquilo, obviamente.'::text),
(402098,44678,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si les vaches s''étaient poussées plus tôt, il ... déjà en route. Une balade tranquille, évidemment.'::text,'serait'::text,'aurait été'::text,'sera'::text,'Si les vaches s''étaient poussées plus tôt, il serait déjà en route. Une balade tranquille, évidemment.'::text),
(402101,44678,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İnekler daha önce çekilseydi, o çoktan yolda ..., sakin bir sürüş tabii.'::text,'olurdu'::text,'olmuş olurdu'::text,'olacak'::text,'İnekler daha önce çekilseydi, o çoktan yolda olurdu, sakin bir sürüş tabii.'::text),
(402102,44678,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a tehenek hamarabb arrébb mentek volna, ő már ... úton. Nyugis bringázás, nyilván.'::text,'lenne'::text,'lett volna'::text,'lesz'::text,'Ha a tehenek hamarabb arrébb mentek volna, ő már lenne úton. Nyugis bringázás, nyilván.'::text),
(373170,41464,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Welpe soll mit legendärer Geduld auf die Wurst ... – ganze sechs Sekunden lang.'::text,'gewartet haben'::text,'warten'::text,'wartend'::text,'Der Welpe soll mit legendärer Geduld auf die Wurst gewartet haben – ganze sechs Sekunden lang.'::text),
(373174,41464,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, цуценя ... на сосиску з легендарним терпінням — цілих шість секунд.'::text,'чекало'::text,'чекає'::text,'чекаючи'::text,'Кажуть, цуценя чекало на сосиску з легендарним терпінням — цілих шість секунд.'::text),
(373173,41464,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Según dicen, el cachorro ... la salchicha con una paciencia legendaria, los seis segundos enteros.'::text,'esperó'::text,'espera'::text,'esperando'::text,'Según dicen, el cachorro esperó la salchicha con una paciencia legendaria, los seis segundos enteros.'::text),
(373172,41464,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chiot ... la saucisse avec une patience légendaire, pendant six secondes entières.'::text,'aurait attendu'::text,'attendrait'::text,'attendant'::text,'Le chiot aurait attendu la saucisse avec une patience légendaire, pendant six secondes entières.'::text),
(373175,41464,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bildirildiğine göre yavru köpek sosis için efsanevi bir sabırla ..., tam altı saniye boyunca.'::text,'beklemiş'::text,'bekliyor'::text,'bekleyerek'::text,'Bildirildiğine göre yavru köpek sosis için efsanevi bir sabırla beklemiş, tam altı saniye boyunca.'::text),
(373176,41464,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hírek szerint a kiskutya legendás türelemmel ... a virslire, mind a hat másodpercig.'::text,'várt'::text,'vár'::text,'várva'::text,'A hírek szerint a kiskutya legendás türelemmel várt a virslire, mind a hat másodpercig.'::text),
(364602,40512,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der kleinere Hund hat seit seiner Ankunft auf dem Rasen viermal mit der Pfote nach dem Wasserstrahl ...'::text,'geschlagen'::text,'geschlagen'::text,'schlägt'::text,'Der kleinere Hund hat seit seiner Ankunft auf dem Rasen viermal mit der Pfote nach dem Wasserstrahl geschlagen.'::text),
(364606,40512,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Менший пес ... лапою по струменю води чотири рази відтоді, як прийшов на газон.'::text,'вдарив'::text,'бив'::text,'б''є'::text,'Менший пес вдарив лапою по струменю води чотири рази відтоді, як прийшов на газон.'::text),
(364605,40512,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El perro más pequeño ... el chorro de agua cuatro veces desde que llegó al césped.'::text,'ha tocado con la pata'::text,'ha estado tocando con la pata'::text,'toca con la pata'::text,'El perro más pequeño ha tocado con la pata el chorro de agua cuatro veces desde que llegó al césped.'::text),
(364604,40512,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le plus petit chien ... le jet d''eau quatre fois depuis son arrivée sur la pelouse.'::text,'a tapé'::text,'n''arrête pas de taper'::text,'tape'::text,'Le plus petit chien a tapé le jet d''eau quatre fois depuis son arrivée sur la pelouse.'::text),
(364607,40512,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Küçük köpek çimenliğe geldiğinden beri su fışkırmasına dört kez pati ...'::text,'attı'::text,'atıyor'::text,'atar'::text,'Küçük köpek çimenliğe geldiğinden beri su fışkırmasına dört kez pati attı.'::text),
(364608,40512,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kisebbik kutya a gyepre érkezése óta négyszer ... a mancsával a vízsugárba.'::text,'csapott'::text,'csapkod'::text,'csap'::text,'A kisebbik kutya a gyepre érkezése óta négyszer csapott a mancsával a vízsugárba.'::text),
(364656,40518,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Hunde hatten den Rasen jahrelang in Ruhe ..., bevor dieser furchtbare Brunnen kam!'::text,'genossen'::text,'genossen'::text,'genossen'::text,'Die Hunde hatten den Rasen jahrelang in Ruhe genossen, bevor dieser furchtbare Brunnen kam!'::text),
(364660,40518,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Собаки ... газоном спокійно роками, поки не з''явився цей жахливий фонтан!'::text,'насолоджувалися'::text,'насолоджуються'::text,'насолоджувалися'::text,'Собаки насолоджувалися газоном спокійно роками, поки не з''явився цей жахливий фонтан!'::text),
(364659,40518,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Los perros ... del césped en paz durante años antes de que llegara esta fuente aterradora!'::text,'habían disfrutado'::text,'han disfrutado'::text,'estaban disfrutando'::text,'¡Los perros habían disfrutado del césped en paz durante años antes de que llegara esta fuente aterradora!'::text),
(364658,40518,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les chiens ... de la pelouse en paix pendant des années avant l''arrivée de cette fontaine terrifiante !'::text,'avaient profité'::text,'ont profité'::text,'profitaient'::text,'Les chiens avaient profité de la pelouse en paix pendant des années avant l''arrivée de cette fontaine terrifiante !'::text),
(364661,40518,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu korkunç çeşme gelmeden önce köpekler yıllarca çimenliğin tadını huzur içinde ...!'::text,'çıkarmıştı'::text,'çıkardı'::text,'çıkarıyordu'::text,'Bu korkunç çeşme gelmeden önce köpekler yıllarca çimenliğin tadını huzur içinde çıkarmıştı!'::text),
(364662,40518,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kutyák évekig békében ... a gyepet, mielőtt megjött ez a félelmetes szökőkút!'::text,'élvezték'::text,'élvezik'::text,'élvezték'::text,'A kutyák évekig békében élvezték a gyepet, mielőtt megjött ez a félelmetes szökőkút!'::text),
(367500,40834,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Schau dich an: Du ... die stylishste Shopperin in diesem ganzen Einkaufszentrum sein.'::text,'musst'::text,'kannst nicht'::text,'darfst nicht'::text,'Schau dich an: Du musst die stylishste Shopperin in diesem ganzen Einkaufszentrum sein.'::text),
