(391236,43471,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora, el elefante ... de nuevo en el mismo escenario.'::text,'estará'::text,'estará'::text,'está'::text,'Mañana a esta hora, el elefante estará de nuevo en el mismo escenario.'::text),
(391235,43471,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à cette heure-ci, l''éléphant ... de nouveau sur la même scène.'::text,'se tiendra'::text,'se tiendra'::text,'se tient'::text,'Demain à cette heure-ci, l''éléphant se tiendra de nouveau sur la même scène.'::text),
(391238,43471,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte fil yine aynı sahnede ...'::text,'duruyor olacak'::text,'duracak'::text,'duruyor'::text,'Yarın bu saatte fil yine aynı sahnede duruyor olacak.'::text),
(391239,43471,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor az elefánt újra ugyanazon a színpadon ...'::text,'fog állni'::text,'fog állni'::text,'áll'::text,'Holnap ilyenkor az elefánt újra ugyanazon a színpadon fog állni.'::text),
(391314,43480,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du hattest die ganze Bühne in Sekunden ... mit Blütenblättern. Ikonisch.'::text,'bedeckt'::text,'zu bedecken'::text,'bedecken'::text,'Ehrlich, du hattest die ganze Bühne in Sekunden bedeckt mit Blütenblättern. Ikonisch.'::text),
(391318,43480,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти за лічені секунди ... всю сцену пелюстками. Культово.'::text,'вкрив'::text,'вкрити'::text,'вкрий'::text,'Чесно, ти за лічені секунди вкрив всю сцену пелюстками. Культово.'::text),
(391317,43480,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De verdad, tú tenías todo el escenario ... de pétalos en segundos. Icónico.'::text,'cubierto'::text,'cubrir'::text,'cubre'::text,'De verdad, tú tenías todo el escenario cubierto de pétalos en segundos. Icónico.'::text),
(391316,43480,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu as fait ... toute la scène de pétales en quelques secondes. Iconique.'::text,'couvrir'::text,'couvrir'::text,'couvre'::text,'Franchement, tu as fait couvrir toute la scène de pétales en quelques secondes. Iconique.'::text),
(391319,43480,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası sen bütün sahneyi saniyeler içinde yapraklarla ..., ikonik.'::text,'kaplattın'::text,'kaplamaya'::text,'kapla'::text,'Açıkçası sen bütün sahneyi saniyeler içinde yapraklarla kaplattın, ikonik.'::text),
(391320,43480,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, te pillanatok alatt ... az egész színpadot szirmokkal. Ikonikus.'::text,'beboríttattad'::text,'beborítani'::text,'borítsd be'::text,'Őszintén, te pillanatok alatt beboríttattad az egész színpadot szirmokkal. Ikonikus.'::text),
(354396,39378,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Katze war begeistert vom Flat Top, und der Gorilla ..., offensichtlich.'::text,'auch'::text,'auch'::text,'auch nicht'::text,'Die Katze war begeistert vom Flat Top, und der Gorilla auch, offensichtlich.'::text),
(354400,39378,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кішка була в захваті від флетопу, і горила ..., очевидно.'::text,'теж'::text,'теж'::text,'теж ні'::text,'Кішка була в захваті від флетопу, і горила теж, очевидно.'::text),
(354399,39378,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El gato estaba encantado con el flat top, y ... el gorila, obviamente.'::text,'también lo estaba'::text,'también lo hizo'::text,'tampoco lo estaba'::text,'El gato estaba encantado con el flat top, y también lo estaba el gorila, obviamente.'::text),
(354398,39378,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chat était ravi de la coupe flat top, et le gorille ..., évidemment.'::text,'aussi'::text,'aussi'::text,'non plus'::text,'Le chat était ravi de la coupe flat top, et le gorille aussi, évidemment.'::text),
(354401,39378,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kedi düz kesimden çok memnundu, goril de ..., tabii ki.'::text,'öyleydi'::text,'öyle yaptı'::text,'değildi'::text,'Kedi düz kesimden çok memnundu, goril de öyleydi, tabii ki.'::text),
(354402,39378,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A macska el volt ragadtatva a flat toptól, és a gorilla ..., nyilván.'::text,'is'::text,'is'::text,'sem'::text,'A macska el volt ragadtatva a flat toptól, és a gorilla is, nyilván.'::text),
(354405,39379,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, bis nächste Woche wird dieser Flat Top wieder zu einem vollen Afro ... sein, kein Witz.'::text,'gewachsen'::text,'gewachsen'::text,'gewachsen'::text,'Bro, bis nächste Woche wird dieser Flat Top wieder zu einem vollen Afro gewachsen sein, kein Witz.'::text),
(354409,39379,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, до наступного тижня цей флетоп ... назад у повне афро, без жартів.'::text,'відросте'::text,'відросте'::text,'відростає'::text,'Бро, до наступного тижня цей флетоп відросте назад у повне афро, без жартів.'::text),
(354408,39379,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, para la semana que viene ese flat top ... hasta ser un afro completo, en serio.'::text,'habrá vuelto a crecer'::text,'volverá a crecer'::text,'vuelve a crecer'::text,'Bro, para la semana que viene ese flat top habrá vuelto a crecer hasta ser un afro completo, en serio.'::text),
(354407,39379,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, d''ici la semaine prochaine, ce flat top ... pour redevenir une afro complète, sans mentir.'::text,'aura repoussé'::text,'repoussera'::text,'repousse'::text,'Frérot, d''ici la semaine prochaine, ce flat top aura repoussé pour redevenir une afro complète, sans mentir.'::text),
(354410,39379,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, gelecek haftaya kadar o düz kesim yeniden kocaman bir afroya ..., yemin ederim.'::text,'dönüşmüş olacak'::text,'dönüşecek'::text,'dönüşür'::text,'Kanka, gelecek haftaya kadar o düz kesim yeniden kocaman bir afroya dönüşmüş olacak, yemin ederim.'::text),
(354411,39379,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, jövő hétre az a flat top ... egy teljes afróvá, komolyan.'::text,'visszanő'::text,'vissza fog nőni'::text,'visszanő'::text,'Tesó, jövő hétre az a flat top visszanő egy teljes afróvá, komolyan.'::text),
(373035,41449,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, du bist heute drei neblige Wege ..., und jeder sah ikonisch aus.'::text,'gewandert'::text,'gewandert'::text,'wanderst'::text,'Ehrlich gesagt, du bist heute drei neblige Wege gewandert, und jeder sah ikonisch aus.'::text),
(373039,41449,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно кажучи, ти сьогодні ... три туманні стежки, і кожна виглядала культово.'::text,'пройшов'::text,'ходив'::text,'ходиш'::text,'Чесно кажучи, ти сьогодні пройшов три туманні стежки, і кожна виглядала культово.'::text),
(373038,41449,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, tú ... tres senderos con niebla hoy, y cada uno se veía icónico.'::text,'has recorrido'::text,'has estado recorriendo'::text,'recorres'::text,'No te voy a mentir, tú has recorrido tres senderos con niebla hoy, y cada uno se veía icónico.'::text),
(373037,41449,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sans mentir, tu ... trois sentiers brumeux aujourd''hui, et chacun avait l''air iconique.'::text,'as parcouru'::text,'as parcouru'::text,'parcours'::text,'Sans mentir, tu as parcouru trois sentiers brumeux aujourd''hui, et chacun avait l''air iconique.'::text),
(373040,41449,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, sen bugün üç sisli patikada ... ve her biri ikonik görünüyordu.'::text,'yürüdün'::text,'yürüyorsun'::text,'yürürsün'::text,'Yalan yok, sen bugün üç sisli patikada yürüdün ve her biri ikonik görünüyordu.'::text),
(373041,41449,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem kamu, te ma három ködös ösvényt ..., és mindegyik ikonikusan nézett ki.'::text,'jártál be'::text,'jártál'::text,'jársz'::text,'Nem kamu, te ma három ködös ösvényt jártál be, és mindegyik ikonikusan nézett ki.'::text),
(373089,41455,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er lief weiter den Weg hinauf, ... der Nebel immer dichter wurde.'::text,'obwohl'::text,'trotz'::text,'damit'::text,'Er lief weiter den Weg hinauf, obwohl der Nebel immer dichter wurde.'::text),
(373093,41455,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ішов далі стежкою вгору, ... туман густішав.'::text,'хоча'::text,'попри'::text,'щоб'::text,'Він ішов далі стежкою вгору, хоча туман густішав.'::text),
(373092,41455,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él siguió subiendo por el sendero ... la niebla se hacía más espesa.'::text,'aunque'::text,'a pesar de'::text,'para que'::text,'Él siguió subiendo por el sendero aunque la niebla se hacía más espesa.'::text),
(373091,41455,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a continué à monter le sentier ... le brouillard s''épaississait.'::text,'même si'::text,'malgré'::text,'pour que'::text,'Il a continué à monter le sentier même si le brouillard s''épaississait.'::text),
(373094,41455,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, sis giderek ... patikadan yukarı yürümeye devam etti.'::text,'yoğunlaşsa da'::text,'yoğunlaşmasına rağmen'::text,'yoğunlaşsın diye'::text,'O, sis giderek yoğunlaşsa da patikadan yukarı yürümeye devam etti.'::text),
(373095,41455,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő tovább ment felfelé az ösvényen, ... a köd egyre sűrűsödött.'::text,'pedig'::text,'annak ellenére'::text,'hogy'::text,'Ő tovább ment felfelé az ösvényen, pedig a köd egyre sűrűsödött.'::text),
(365412,40602,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich ... das Foto gemacht, während die fünf Jungs am See lagen.'::text,'wurde'::text,'machte'::text,'wird'::text,'Mädel, angeblich wurde das Foto gemacht, während die fünf Jungs am See lagen.'::text),
(365416,40602,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, фото ..., поки п''ятеро хлопців лежали біля озера.'::text,'було зроблено'::text,'зробило'::text,'роблять'::text,'Подруго, кажуть, фото було зроблено, поки п''ятеро хлопців лежали біля озера.'::text),
(365415,40602,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer la foto ... mientras los cinco chicos estaban tumbados junto al lago.'::text,'fue tomada'::text,'tomó'::text,'es tomada'::text,'Amiga, al parecer la foto fue tomada mientras los cinco chicos estaban tumbados junto al lago.'::text),
(365414,40602,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment la photo ... pendant que les cinq garçons étaient allongés au bord du lac.'::text,'a été prise'::text,'a pris'::text,'est prise'::text,'Meuf, apparemment la photo a été prise pendant que les cinq garçons étaient allongés au bord du lac.'::text),
(365417,40602,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre fotoğraf, beş çocuk gölün kenarında yatarken ...'::text,'çekildi'::text,'çekti'::text,'çekiliyor'::text,'Kızım, duyduğuma göre fotoğraf, beş çocuk gölün kenarında yatarken çekildi.'::text),
(365418,40602,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a fotó akkor ..., amikor az öt srác a tónál feküdt.'::text,'készült'::text,'készített'::text,'készül'::text,'Csajszi, állítólag a fotó akkor készült, amikor az öt srác a tónál feküdt.'::text),
(365475,40609,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... hier schon seit Stunden, und keiner will sich jemals wieder bewegen!'::text,'liegen'::text,'liegen'::text,'liegen'::text,'Sie liegen hier schon seit Stunden, und keiner will sich jemals wieder bewegen!'::text),
(365479,40609,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... тут уже кілька годин, і ніхто більше ніколи не хоче рухатися!'::text,'лежать'::text,'лежать'::text,'лежать'::text,'Вони лежать тут уже кілька годин, і ніхто більше ніколи не хоче рухатися!'::text),
(365478,40609,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ellos ... aquí desde hace horas, y nadie quiere volver a moverse jamás!'::text,'han estado tumbados'::text,'están tumbados'::text,'se tumban'::text,'¡Ellos han estado tumbados aquí desde hace horas, y nadie quiere volver a moverse jamás!'::text),
(365477,40609,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... là depuis des heures, et personne ne veut plus jamais bouger !'::text,'sont allongés'::text,'sont allongés'::text,'s''allongent'::text,'Ils sont allongés là depuis des heures, et personne ne veut plus jamais bouger !'::text),
(365480,40609,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar saatlerdir burada ... ve kimse bir daha asla kıpırdamak istemiyor!'::text,'yatıyor'::text,'yatıyor'::text,'yatar'::text,'Onlar saatlerdir burada yatıyor ve kimse bir daha asla kıpırdamak istemiyor!'::text),
(365481,40609,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ők órák óta itt ..., és senki nem akar többé megmozdulni!'::text,'fekszenek'::text,'fekszenek'::text,'fekszenek'::text,'Ők órák óta itt fekszenek, és senki nem akar többé megmozdulni!'::text),
(334677,37187,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Tonne nicht so tief wäre, ... der Waschbär leicht raus.'::text,'kletterte'::text,'klettert'::text,'klettert'::text,'Wenn die Tonne nicht so tief wäre, kletterte der Waschbär leicht raus.'::text),
(334681,37187,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби бак не був таким глибоким, єнот легко ...'::text,'виліз би'::text,'вилізе'::text,'лізе'::text,'Якби бак не був таким глибоким, єнот легко виліз би.'::text),
(334680,37187,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el contenedor no fuera tan hondo, el mapache ... fácilmente.'::text,'saldría'::text,'saldrá'::text,'sale'::text,'Si el contenedor no fuera tan hondo, el mapache saldría fácilmente.'::text),
(334679,37187,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la poubelle n''était pas si profonde, le raton laveur ... facilement.'::text,'sortirait'::text,'sortira'::text,'sort'::text,'Si la poubelle n''était pas si profonde, le raton laveur sortirait facilement.'::text),
(334682,37187,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çöp kutusu bu kadar derin olmasaydı, rakun kolayca ...'::text,'tırmanıp çıkardı'::text,'tırmanıp çıkacak'::text,'tırmanıp çıkar'::text,'Çöp kutusu bu kadar derin olmasaydı, rakun kolayca tırmanıp çıkardı.'::text),
(334683,37187,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a kuka nem lenne ilyen mély, a mosómedve könnyen ...'::text,'kimászna'::text,'ki fog mászni'::text,'kimászik'::text,'Ha a kuka nem lenne ilyen mély, a mosómedve könnyen kimászna.'::text),
(334722,37192,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Waschbär sitzt ... der Tonne, neben einem Müllsack.'::text,'am Boden'::text,'an einem Boden'::text,'an Boden'::text,'Der Waschbär sitzt am Boden der Tonne, neben einem Müllsack.'::text),
(334726,37192,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Єнот сидить на ... бака, поруч із пакетом для сміття.'::text,'дні'::text,'дні'::text,'дні'::text,'Єнот сидить на дні бака, поруч із пакетом для сміття.'::text),
(334725,37192,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El mapache está sentado en ... del contenedor, junto a una bolsa de basura.'::text,'el fondo'::text,'un fondo'::text,'fondo'::text,'El mapache está sentado en el fondo del contenedor, junto a una bolsa de basura.'::text),
(334724,37192,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le raton laveur est assis ... de la poubelle, à côté d''un sac poubelle.'::text,'au fond'::text,'à un fond'::text,'à fond'::text,'Le raton laveur est assis au fond de la poubelle, à côté d''un sac poubelle.'::text),
(334727,37192,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rakun çöp kutusunun ..., bir çöp poşetinin yanında oturuyor.'::text,'dibinde'::text,'bir dibinde'::text,'dibinde'::text,'Rakun çöp kutusunun dibinde, bir çöp poşetinin yanında oturuyor.'::text),
(334728,37192,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A mosómedve a kuka ... ül, egy szemeteszsák mellett.'::text,'alján'::text,'egy alján'::text,'alján'::text,'A mosómedve a kuka alján ül, egy szemeteszsák mellett.'::text),
(348096,38678,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, morgen um diese Zeit ... er sich nach jedem Ball ins Meer, kein Witz.'::text,'hechtet'::text,'hechtet'::text,'hechtet'::text,'Bro, morgen um diese Zeit hechtet er sich nach jedem Ball ins Meer, kein Witz.'::text),
(348100,38678,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, завтра в цей час він ... в море за кожним м''ячем, без жартів.'::text,'пірнатиме'::text,'пірне'::text,'пірнає'::text,'Бро, завтра в цей час він пірнатиме в море за кожним м''ячем, без жартів.'::text),
(348099,38678,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, mañana a esta hora él ... al mar detrás de cada balón, en serio.'::text,'estará tirándose'::text,'se tirará'::text,'se tira'::text,'Bro, mañana a esta hora él estará tirándose al mar detrás de cada balón, en serio.'::text),
(348098,38678,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, demain à cette heure-ci il ... dans la mer après chaque ballon, sans mentir.'::text,'sera en train de plonger'::text,'plongera'::text,'plonge'::text,'Frérot, demain à cette heure-ci il sera en train de plonger dans la mer après chaque ballon, sans mentir.'::text),
(348101,38678,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, yarın bu saatte o her topun peşinden denize ..., yemin ederim.'::text,'dalıyor olacak'::text,'dalacak'::text,'dalar'::text,'Kanka, yarın bu saatte o her topun peşinden denize dalıyor olacak, yemin ederim.'::text),
(348102,38678,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, holnap ilyenkor ő minden labda után ... a tengerbe, komolyan.'::text,'fog vetődni'::text,'vetődik majd'::text,'vetődik'::text,'Tesó, holnap ilyenkor ő minden labda után fog vetődni a tengerbe, komolyan.'::text),
(348168,38686,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Sonnenuntergang ... er etwa fünfzigmal ins Meer. Klar, ein entspannter Strandtag.'::text,'springt'::text,'springt'::text,'springt gerade'::text,'Bis zum Sonnenuntergang springt er etwa fünfzigmal ins Meer. Klar, ein entspannter Strandtag.'::text),
(348172,38686,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До заходу сонця він ... в море разів п''ятдесят. Явно розслаблений день на пляжі.'::text,'пірне'::text,'пірне'::text,'пірнатиме'::text,'До заходу сонця він пірне в море разів п''ятдесят. Явно розслаблений день на пляжі.'::text),
(348171,38686,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el atardecer, él ... al mar unas cincuenta veces. Claramente un día de playa relajante.'::text,'se habrá tirado'::text,'se tirará'::text,'se estará tirando'::text,'Para el atardecer, él se habrá tirado al mar unas cincuenta veces. Claramente un día de playa relajante.'::text),
(348170,38686,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le coucher du soleil, il ... dans la mer une cinquantaine de fois. Clairement une journée plage reposante.'::text,'aura plongé'::text,'plongera'::text,'sera en train de plonger'::text,'D''ici le coucher du soleil, il aura plongé dans la mer une cinquantaine de fois. Clairement une journée plage reposante.'::text),
(348173,38686,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımına kadar o denize yaklaşık elli kez ..., belli ki dinlendirici bir plaj günü.'::text,'dalmış olacak'::text,'dalacak'::text,'dalıyor olacak'::text,'Gün batımına kadar o denize yaklaşık elli kez dalmış olacak, belli ki dinlendirici bir plaj günü.'::text),
(348174,38686,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Naplementéig ő nagyjából ötvenszer ... a tengerbe. Nyilván egy pihentető strandnap.'::text,'vetődik be'::text,'fog vetődni'::text,'fog épp vetődni'::text,'Naplementéig ő nagyjából ötvenszer vetődik be a tengerbe. Nyilván egy pihentető strandnap.'::text),
(351156,39018,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... gerade ins Meer, als er hinfiel, also war er im Meer erschöpft.'::text,'ging'::text,'ging'::text,'ist gegangen'::text,'Er ging gerade ins Meer, als er hinfiel, also war er im Meer erschöpft.'::text),
(351160,39018,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... в море, коли впав, тож він був виснажений у морі.'::text,'ішов'::text,'пішов'::text,'пішов'::text,'Він ішов в море, коли впав, тож він був виснажений у морі.'::text),
(351159,39018,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... hacia el mar cuando se cayó, así que estaba agotado en el mar.'::text,'estaba caminando'::text,'caminó'::text,'ha caminado'::text,'Él estaba caminando hacia el mar cuando se cayó, así que estaba agotado en el mar.'::text),
(351158,39018,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... vers la mer quand il est tombé, donc il était épuisé dans la mer.'::text,'marchait'::text,'a marché'::text,'a marché'::text,'Il marchait vers la mer quand il est tombé, donc il était épuisé dans la mer.'::text),
(351161,39018,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O düştüğünde denize doğru ..., yani denizde bitkin düşmüştü.'::text,'yürüyordu'::text,'yürüdü'::text,'yürüdü'::text,'O düştüğünde denize doğru yürüyordu, yani denizde bitkin düşmüştü.'::text),
(351162,39018,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő a tenger felé ..., amikor elesett, szóval a tengerben volt kimerült.'::text,'sétált'::text,'sétált'::text,'sétált'::text,'Ő a tenger felé sétált, amikor elesett, szóval a tengerben volt kimerült.'::text),
(351246,39028,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Meeting um 9 Uhr wird er sich von dieser Erschöpfung ...'::text,'erholt haben'::text,'erholen'::text,'erholt'::text,'Bis zum Meeting um 9 Uhr wird er sich von dieser Erschöpfung erholt haben.'::text),
(351250,39028,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До наради о 9:00 він ... після такого виснаження.'::text,'відновиться'::text,'відновиться'::text,'відновлюється'::text,'До наради о 9:00 він відновиться після такого виснаження.'::text),
(351249,39028,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para la reunión de las 9:00, él ya se ... de este agotamiento.'::text,'habrá recuperado'::text,'recuperará'::text,'recupera'::text,'Para la reunión de las 9:00, él ya se habrá recuperado de este agotamiento.'::text),
(351248,39028,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la réunion de 9 h, il se ... de cet épuisement.'::text,'sera remis'::text,'remettra'::text,'remet'::text,'D''ici la réunion de 9 h, il se sera remis de cet épuisement.'::text),
(351251,39028,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saat 9''daki toplantıya kadar o, bu bitkinlikten ...'::text,'kurtulmuş olacak'::text,'kurtulacak'::text,'kurtulur'::text,'Saat 9''daki toplantıya kadar o, bu bitkinlikten kurtulmuş olacak.'::text),
(351252,39028,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A 9 órás meetingre ő ... ebből a kimerültségből.'::text,'rendbe jön'::text,'rendbe fog jönni'::text,'rendbe jön'::text,'A 9 órás meetingre ő rendbe jön ebből a kimerültségből.'::text),
(366933,40771,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann ... sein Luxusauto schon seit zwanzig Minuten.'::text,'bewundert'::text,'bewundert'::text,'bewundert'::text,'Der Mann bewundert sein Luxusauto schon seit zwanzig Minuten.'::text),
(366937,40771,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік ... своїм розкішним авто вже двадцять хвилин.'::text,'милується'::text,'милується'::text,'милується'::text,'Чоловік милується своїм розкішним авто вже двадцять хвилин.'::text),
(366936,40771,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre ... su coche de lujo desde hace veinte minutos.'::text,'ha estado admirando'::text,'está admirando'::text,'admira'::text,'El hombre ha estado admirando su coche de lujo desde hace veinte minutos.'::text),
(366935,40771,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme ... sa voiture de luxe depuis vingt minutes.'::text,'admire'::text,'admire'::text,'admire'::text,'L''homme admire sa voiture de luxe depuis vingt minutes.'::text),
(366938,40771,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam yirmi dakikadır lüks arabasını ...'::text,'hayranlıkla izliyor'::text,'hayranlıkla izliyor'::text,'hayranlıkla izler'::text,'Adam yirmi dakikadır lüks arabasını hayranlıkla izliyor.'::text),
(366939,40771,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi húsz perce ... a luxusautóját.'::text,'csodálja'::text,'csodálja'::text,'csodálja'::text,'A férfi húsz perce csodálja a luxusautóját.'::text),
(358230,39804,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo Bro, dieser Riese hat nicht geschlafen, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Yo Bro, dieser Riese hat nicht geschlafen, oder?'::text),
(358234,39804,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, бро, той велетень не спав, ...?'::text,'так'::text,'так'::text,'так'::text,'Йо, бро, той велетень не спав, так?'::text),
(358233,39804,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey bro, ese gigante no estaba dormido, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Ey bro, ese gigante no estaba dormido, ¿verdad?'::text),
(358232,39804,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo frérot, ce géant ne dormait pas, ... ?'::text,'hein'::text,'hein'::text,'hein'::text,'Yo frérot, ce géant ne dormait pas, hein ?'::text),
(358235,39804,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o dev uyumuyordu, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Kanka, o dev uyumuyordu, değil mi?'::text),
(358236,39804,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az az óriás nem aludt, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'Tesó, az az óriás nem aludt, ugye?'::text),
(358275,39809,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn das kleine Tier nicht gefallen wäre, ... es nicht auf dem Kopf des Riesen gelandet.'::text,'wäre'::text,'wird'::text,'ist'::text,'Wenn das kleine Tier nicht gefallen wäre, wäre es nicht auf dem Kopf des Riesen gelandet.'::text),
(358279,39809,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби маленька тваринка не впала, вона ... на голову велетня.'::text,'не приземлилася б'::text,'не приземлиться'::text,'не приземлилася'::text,'Якби маленька тваринка не впала, вона не приземлилася б на голову велетня.'::text),
(358278,39809,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el animalito no se hubiera caído, él no ... en la cabeza del gigante.'::text,'habría aterrizado'::text,'aterrizará'::text,'aterrizó'::text,'Si el animalito no se hubiera caído, él no habría aterrizado en la cabeza del gigante.'::text),
(358277,39809,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le petit animal n''était pas tombé, il ... sur la tête du géant.'::text,'n''aurait pas atterri'::text,'n''atterrira pas'::text,'n''a pas atterri'::text,'Si le petit animal n''était pas tombé, il n''aurait pas atterri sur la tête du géant.'::text),
(358280,39809,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Küçük hayvan düşmeseydi, o devin başına ...'::text,'konmazdı'::text,'konmayacak'::text,'konmadı'::text,'Küçük hayvan düşmeseydi, o devin başına konmazdı.'::text),
(358281,39809,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a kis állat nem esik le, ő nem ... az óriás fejére.'::text,'landolt volna'::text,'fog landolni'::text,'landolt'::text,'Ha a kis állat nem esik le, ő nem landolt volna az óriás fejére.'::text),
(390225,43359,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Fahrzeug ... über die Landstraße, bevor es bei den Dünen geparkt wurde, wie beobachtet.'::text,'war gerast'::text,'ist gerast'::text,'rast'::text,'Das Fahrzeug war gerast über die Landstraße, bevor es bei den Dünen geparkt wurde, wie beobachtet.'::text),
(390229,43359,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Автомобіль ... сільською дорогою, перш ніж його припаркували біля дюн, як було зафіксовано.'::text,'мчав'::text,'мчав'::text,'мчить'::text,'Автомобіль мчав сільською дорогою, перш ніж його припаркували біля дюн, як було зафіксовано.'::text),
(390228,43359,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El vehículo ... por la carretera rural antes de ser aparcado junto a las dunas, según lo observado.'::text,'había circulado a toda velocidad'::text,'ha circulado a toda velocidad'::text,'circula a toda velocidad'::text,'El vehículo había circulado a toda velocidad por la carretera rural antes de ser aparcado junto a las dunas, según lo observado.'::text),
(390227,43359,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le véhicule ... sur la route de campagne avant d''être garé près des dunes, comme observé.'::text,'avait filé'::text,'a filé'::text,'file'::text,'Le véhicule avait filé sur la route de campagne avant d''être garé près des dunes, comme observé.'::text),
(390230,43359,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Araç, gözlemlendiği üzere, kumulların yanına park edilmeden önce köy yolunda ...'::text,'hızla ilerlemişti'::text,'hızla ilerledi'::text,'hızla ilerler'::text,'Araç, gözlemlendiği üzere, kumulların yanına park edilmeden önce köy yolunda hızla ilerlemişti.'::text),
(390231,43359,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A jármű ... a vidéki úton, mielőtt leparkolták a dűnéknél, ahogy megfigyelték.'::text,'száguldott'::text,'száguldott'::text,'száguld'::text,'A jármű száguldott a vidéki úton, mielőtt leparkolták a dűnéknél, ahogy megfigyelték.'::text),
(390261,43363,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann, ... Auto vorhin über die Straße gerast ist, geht darauf zu.'::text,'dessen'::text,'der'::text,'das'::text,'Der Mann, dessen Auto vorhin über die Straße gerast ist, geht darauf zu.'::text),
(390265,43363,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік, ... авто раніше мчало дорогою, підходить до нього.'::text,'чиє'::text,'який'::text,'яке'::text,'Чоловік, чиє авто раніше мчало дорогою, підходить до нього.'::text),
(390264,43363,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre, ... coche iba a toda velocidad por la carretera antes, se acerca a él.'::text,'cuyo'::text,'que'::text,'el cual'::text,'El hombre, cuyo coche iba a toda velocidad por la carretera antes, se acerca a él.'::text),
(390263,43363,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme, ... la voiture filait sur la route tout à l''heure, s''en approche.'::text,'dont'::text,'qui'::text,'laquelle'::text,'L''homme, dont la voiture filait sur la route tout à l''heure, s''en approche.'::text),
(390266,43363,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam, ... arabası daha önce yolda hızla gidiyordu, ona doğru yürüyor.'::text,'ki'::text,'kim'::text,'hangi'::text,'Adam, ki arabası daha önce yolda hızla gidiyordu, ona doğru yürüyor.'::text),
(390267,43363,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi, ... autója korábban száguldott az úton, odasétál hozzá.'::text,'akinek az'::text,'aki'::text,'amely'::text,'A férfi, akinek az autója korábban száguldott az úton, odasétál hozzá.'::text),
(400494,44500,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Fahrzeug ... die ganze Zeit in einem dunklen Anhänger. Absolut unglaublich!'::text,'war versteckt'::text,'versteckte sich'::text,'versteckt sich'::text,'Das Fahrzeug war versteckt die ganze Zeit in einem dunklen Anhänger. Absolut unglaublich!'::text),
(400498,44500,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Автомобіль ... весь час у темному причепі. Просто неймовірно!'::text,'був схований'::text,'ховався'::text,'ховається'::text,'Автомобіль був схований весь час у темному причепі. Просто неймовірно!'::text),
(400497,44500,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El vehículo ... dentro de un remolque oscuro todo el tiempo. ¡Absolutamente increíble!'::text,'estaba escondido'::text,'se escondió'::text,'se está escondiendo'::text,'El vehículo estaba escondido dentro de un remolque oscuro todo el tiempo. ¡Absolutamente increíble!'::text),
(400496,44500,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le véhicule ... dans une remorque sombre depuis le début. Absolument incroyable !'::text,'était caché'::text,'se cachait'::text,'se cache'::text,'Le véhicule était caché dans une remorque sombre depuis le début. Absolument incroyable !'::text),
(400499,44500,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Araç bütün bu süre boyunca karanlık bir römorkun içinde ..., inanılmaz!'::text,'saklanmıştı'::text,'saklandı'::text,'saklanıyor'::text,'Araç bütün bu süre boyunca karanlık bir römorkun içinde saklanmıştı, inanılmaz!'::text),
(400500,44500,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A jármű végig ... egy sötét utánfutóban. Egyszerűen hihetetlen!'::text,'el volt rejtve'::text,'elrejtőzött'::text,'rejtőzik'::text,'A jármű végig el volt rejtve egy sötét utánfutóban. Egyszerűen hihetetlen!'::text),
(400557,44507,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Anhänger öffnet sich, und ... darin ist ein Sportwagen.'::text,'das Fahrzeug'::text,'ein Fahrzeug'::text,'Fahrzeug'::text,'Der Anhänger öffnet sich, und das Fahrzeug darin ist ein Sportwagen.'::text),
(400561,44507,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Причіп відчиняється, і ... в ньому — спортивне авто.'::text,'автомобіль'::text,'автомобіль'::text,'автомобіль'::text,'Причіп відчиняється, і автомобіль в ньому — спортивне авто.'::text),
(400560,44507,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El remolque se abre, y ... que hay dentro es un deportivo.'::text,'el vehículo'::text,'un vehículo'::text,'vehículo'::text,'El remolque se abre, y el vehículo que hay dentro es un deportivo.'::text),
(400559,44507,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La remorque s''ouvre, et ... à l''intérieur est une voiture de sport.'::text,'le véhicule'::text,'un véhicule'::text,'véhicule'::text,'La remorque s''ouvre, et le véhicule à l''intérieur est une voiture de sport.'::text),
(400562,44507,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Römork açılıyor ve içindeki ... bir spor araba.'::text,'araç'::text,'bir araç'::text,'araç'::text,'Römork açılıyor ve içindeki araç bir spor araba.'::text),
(400563,44507,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az utánfutó kinyílik, és ... benne egy sportautó.'::text,'a jármű'::text,'egy jármű'::text,'jármű'::text,'Az utánfutó kinyílik, és a jármű benne egy sportautó.'::text),
(330951,36773,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also angeblich ... er früher Angst vor Robotern, und jetzt lässt er einen an sich heran.'::text,'hatte'::text,'hätte'::text,'ist gewohnt zu haben'::text,'Okay, also angeblich hatte er früher Angst vor Robotern, und jetzt lässt er einen an sich heran.'::text),
(330955,36773,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, кажуть, він ... боявся роботів, а тепер дозволяє одному до нього підійти.'::text,'колись'::text,'би'::text,'звично'::text,'Коротше, кажуть, він колись боявся роботів, а тепер дозволяє одному до нього підійти.'::text),
(330954,36773,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues al parecer él ... tenerles miedo a los robots, y ahora deja que uno se le acerque.'::text,'solía'::text,'solía'::text,'está acostumbrado a'::text,'Vale, pues al parecer él solía tenerles miedo a los robots, y ahora deja que uno se le acerque.'::text),
(330953,36773,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon alors, apparemment il ... peur des robots, et maintenant il laisse l''un d''eux s''approcher de lui.'::text,'avait'::text,'aurait'::text,'est habitué à avoir'::text,'Bon alors, apparemment il avait peur des robots, et maintenant il laisse l''un d''eux s''approcher de lui.'::text),
(330956,36773,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam yani, duyduğuma göre o eskiden robotlardan ... ve şimdi birinin kendisine yaklaşmasına izin veriyor.'::text,'korkardı'::text,'korkardı'::text,'korkmaya alışkın'::text,'Tamam yani, duyduğuma göre o eskiden robotlardan korkardı ve şimdi birinin kendisine yaklaşmasına izin veriyor.'::text),
(330957,36773,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval állítólag ő régen ... a robotoktól, most meg hagyja, hogy az egyik odamenjen hozzá.'::text,'félt'::text,'félt volna'::text,'hozzá van szokva, hogy féljen'::text,'Oké, szóval állítólag ő régen félt a robotoktól, most meg hagyja, hogy az egyik odamenjen hozzá.'::text),
(378003,42001,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie sich angemeldet hätte, ... sie jetzt an der Kamera vorbei. Ein klarer Verlust für das Rennen.'::text,'liefe'::text,'wäre gelaufen'::text,'wird laufen'::text,'Wenn sie sich angemeldet hätte, liefe sie jetzt an der Kamera vorbei. Ein klarer Verlust für das Rennen.'::text),
(378007,42001,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона зареєструвалася, то зараз ... повз камеру. Явна втрата для забігу.'::text,'бігла б'::text,'бігла б'::text,'бігтиме'::text,'Якби вона зареєструвалася, то зараз бігла б повз камеру. Явна втрата для забігу.'::text),
(378006,42001,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ella se hubiera apuntado, ahora ... por delante de la cámara. Una pérdida para la carrera, claramente.'::text,'estaría corriendo'::text,'habría corrido'::text,'correrá'::text,'Si ella se hubiera apuntado, ahora estaría corriendo por delante de la cámara. Una pérdida para la carrera, claramente.'::text),
(378005,42001,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle s''était inscrite, elle ... devant la caméra en ce moment. Une perte pour la course, clairement.'::text,'courrait'::text,'aurait couru'::text,'courra'::text,'Si elle s''était inscrite, elle courrait devant la caméra en ce moment. Une perte pour la course, clairement.'::text),
(378008,42001,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O kayıt olsaydı, şu an kameranın önünden koşarak ..., yarış için büyük kayıp tabii.'::text,'geçiyor olurdu'::text,'geçmiş olurdu'::text,'geçecek'::text,'O kayıt olsaydı, şu an kameranın önünden koşarak geçiyor olurdu, yarış için büyük kayıp tabii.'::text),
(378009,42001,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ő benevezett volna, most ... a kamera előtt. Nyilván nagy veszteség a versenynek.'::text,'futna el'::text,'futott volna el'::text,'fog elfutni'::text,'Ha ő benevezett volna, most futna el a kamera előtt. Nyilván nagy veszteség a versenynek.'::text),
(358140,39794,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also angeblich ... ein Riesenfisch den ganzen Nachmittag diesen armen Otter.'::text,'beobachtete'::text,'wurde beobachtet'::text,'beobachtend'::text,'Okay, also angeblich beobachtete ein Riesenfisch den ganzen Nachmittag diesen armen Otter.'::text),
(358144,39794,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, кажуть, величезна риба ... за тією бідною видрою всю другу половину дня.'::text,'стежила'::text,'була під наглядом'::text,'стежачи'::text,'Коротше, кажуть, величезна риба стежила за тією бідною видрою всю другу половину дня.'::text),
(358143,39794,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues al parecer un pez gigante ... a esa pobre nutria toda la tarde.'::text,'observó'::text,'fue observado'::text,'observando'::text,'Vale, pues al parecer un pez gigante observó a esa pobre nutria toda la tarde.'::text),
(358142,39794,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon alors, apparemment un poisson géant ... cette pauvre loutre tout l''après-midi.'::text,'a observé'::text,'a été observé'::text,'observant'::text,'Bon alors, apparemment un poisson géant a observé cette pauvre loutre tout l''après-midi.'::text),
(358145,39794,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam yani, duyduğuma göre dev bir balık bütün öğleden sonra o zavallı su samurunu ...'::text,'izledi'::text,'izlendi'::text,'izleyerek'::text,'Tamam yani, duyduğuma göre dev bir balık bütün öğleden sonra o zavallı su samurunu izledi.'::text),
(358146,39794,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval állítólag egy óriási hal egész délután ... azt a szegény vidrát.'::text,'figyelte'::text,'meg lett figyelve'::text,'figyelve'::text,'Oké, szóval állítólag egy óriási hal egész délután figyelte azt a szegény vidrát.'::text),
(358149,39795,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, ich hab gehört, der Otter ... die Stange stundenlang umklammert, bevor der Riesenfisch auftauchte.'::text,'hatte'::text,'hat'::text,'umarmt'::text,'Hör mal, ich hab gehört, der Otter hatte die Stange stundenlang umklammert, bevor der Riesenfisch auftauchte.'::text),
(358153,39795,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що видра ... жердину годинами, поки не з''явилася величезна риба.'::text,'обіймала'::text,'обіймає'::text,'обіймає'::text,'Слухай, я чула, що видра обіймала жердину годинами, поки не з''явилася величезна риба.'::text),
(358152,39795,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, yo oí que la nutria ... abrazada al palo durante horas antes de que apareciera el pez gigante.'::text,'había estado'::text,'ha estado'::text,'está'::text,'Oye, yo oí que la nutria había estado abrazada al palo durante horas antes de que apareciera el pez gigante.'::text),
(358151,39795,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu dire que la loutre ... le poteau depuis des heures quand le poisson géant est arrivé.'::text,'serrait'::text,'serre'::text,'serre'::text,'Écoute, j''ai entendu dire que la loutre serrait le poteau depuis des heures quand le poisson géant est arrivé.'::text),
(358154,39795,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, ben duydum ki dev balık ortaya çıkmadan önce su samuru saatlerce direğe ...'::text,'sarılıyormuş'::text,'sarılıyor'::text,'sarılır'::text,'Dinle, ben duydum ki dev balık ortaya çıkmadan önce su samuru saatlerce direğe sarılıyormuş.'::text),
(358155,39795,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, én úgy hallottam, a vidra órák óta ... a rudat, mielőtt megjelent az óriáshal.'::text,'ölelte'::text,'öleli'::text,'öleli'::text,'Figyelj, én úgy hallottam, a vidra órák óta ölelte a rudat, mielőtt megjelent az óriáshal.'::text),
(375060,41674,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein Platz ist ein Ort, ... es viel Raum gibt, also ist dieser Platz geräumig.'::text,'wo'::text,'der'::text,'wer'::text,'Ein Platz ist ein Ort, wo es viel Raum gibt, also ist dieser Platz geräumig.'::text),
(375064,41674,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Площа — це місце, ... багато простору, тож ця площа простора.'::text,'де'::text,'яке'::text,'хто'::text,'Площа — це місце, де багато простору, тож ця площа простора.'::text),
(375063,41674,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una plaza es un lugar ... hay mucho espacio, así que esta plaza es espaciosa.'::text,'donde'::text,'que'::text,'quien'::text,'Una plaza es un lugar donde hay mucho espacio, así que esta plaza es espaciosa.'::text),
(375062,41674,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une place, c''est un endroit ... il y a beaucoup d''espace, donc cette place est spacieuse.'::text,'où'::text,'que'::text,'qui'::text,'Une place, c''est un endroit où il y a beaucoup d''espace, donc cette place est spacieuse.'::text),
(375065,41674,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meydan, bol alan ... bir yerdir, yani bu meydan geniştir.'::text,'olan'::text,'hangi'::text,'kim'::text,'Meydan, bol alan olan bir yerdir, yani bu meydan geniştir.'::text),
(375066,41674,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tér olyan hely, ... sok hely van, szóval ez a tér tágas.'::text,'ahol'::text,'amely'::text,'aki'::text,'A tér olyan hely, ahol sok hely van, szóval ez a tér tágas.'::text),
(375114,41680,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Auto ... bereits 3 Stunden auf dem Platz geparkt, bevor das Meeting begann.'::text,'war'::text,'ist'::text,'ist'::text,'Das Auto war bereits 3 Stunden auf dem Platz geparkt, bevor das Meeting begann.'::text),
(375118,41680,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Авто ... на площі 3 години, перш ніж почалася нарада.'::text,'стояло'::text,'стоїть'::text,'стоїть'::text,'Авто стояло на площі 3 години, перш ніж почалася нарада.'::text),
(375117,41680,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El coche ... aparcado en la plaza 3 horas antes de que empezara la reunión.'::text,'llevaba'::text,'lleva'::text,'está'::text,'El coche llevaba aparcado en la plaza 3 horas antes de que empezara la reunión.'::text),
(375116,41680,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La voiture ... garée sur la place depuis 3 heures quand la réunion a commencé.'::text,'était'::text,'est'::text,'est'::text,'La voiture était garée sur la place depuis 3 heures quand la réunion a commencé.'::text),
(375119,41680,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toplantı başlamadan önce araba 3 saattir meydanda park halinde ...'::text,'duruyordu'::text,'duruyor'::text,'duruyor'::text,'Toplantı başlamadan önce araba 3 saattir meydanda park halinde duruyordu.'::text),
(375120,41680,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az autó már 3 órája ... a téren, amikor elkezdődött a meeting.'::text,'parkolt'::text,'parkol'::text,'parkol'::text,'Az autó már 3 órája parkolt a téren, amikor elkezdődött a meeting.'::text),
(351426,39048,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sie den Ausgang erreichten, hatten sich die Augen des Reiters schon an die Dunkelheit ...'::text,'gewöhnt'::text,'gewöhnt'::text,'gewöhnen'::text,'Als sie den Ausgang erreichten, hatten sich die Augen des Reiters schon an die Dunkelheit gewöhnt.'::text),
(351430,39048,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли вони дісталися виходу, очі вершника вже ... до темряви.'::text,'звикли'::text,'звикли'::text,'звикають'::text,'Коли вони дісталися виходу, очі вершника вже звикли до темряви.'::text),
(351429,39048,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando llegaron a la salida, los ojos del jinete ya se ... a la oscuridad.'::text,'habían adaptado'::text,'han adaptado'::text,'adaptan'::text,'Cuando llegaron a la salida, los ojos del jinete ya se habían adaptado a la oscuridad.'::text),
(351428,39048,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand ils ont atteint la sortie, les yeux du cavalier ... à l''obscurité.'::text,'s''étaient habitués'::text,'se sont habitués'::text,'s''habituent'::text,'Quand ils ont atteint la sortie, les yeux du cavalier s''étaient habitués à l''obscurité.'::text),
(351431,39048,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çıkışa vardıklarında binicinin gözleri karanlığa ...'::text,'alışmıştı'::text,'alıştı'::text,'alışır'::text,'Çıkışa vardıklarında binicinin gözleri karanlığa alışmıştı.'::text),
(351432,39048,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire elérték a kijáratot, a lovas szeme már ... a sötéthez.'::text,'hozzászokott'::text,'hozzászokott'::text,'hozzászokik'::text,'Mire elérték a kijáratot, a lovas szeme már hozzászokott a sötéthez.'::text),
(351471,39053,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Ausgang ... immer näher, und der Albtraum ist vorbei!'::text,'kommt'::text,'kommt'::text,'ist gekommen'::text,'Der Ausgang kommt immer näher, und der Albtraum ist vorbei!'::text),
(351475,39053,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вихід ... все ближче й ближче, і жахіттю кінець!'::text,'наближається'::text,'наближається'::text,'наблизився'::text,'Вихід наближається все ближче й ближче, і жахіттю кінець!'::text),
(351474,39053,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La salida ... cada vez más cerca, y la pesadilla se acaba!'::text,'se ve'::text,'se ve'::text,'se ha visto'::text,'¡La salida se ve cada vez más cerca, y la pesadilla se acaba!'::text),
(351473,39053,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La sortie ... de plus en plus proche, et le cauchemar est fini !'::text,'devient'::text,'devient'::text,'est devenue'::text,'La sortie devient de plus en plus proche, et le cauchemar est fini !'::text),
(351476,39053,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çıkış gitgide ... ve kâbus bitti!'::text,'yaklaşıyor'::text,'yaklaşır'::text,'yaklaştı'::text,'Çıkış gitgide yaklaşıyor ve kâbus bitti!'::text),
(351477,39053,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kijárat egyre közelebb ..., és vége a rémálomnak!'::text,'kerül'::text,'kerül'::text,'került'::text,'A kijárat egyre közelebb kerül, és vége a rémálomnak!'::text),
(344307,38257,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich hat der Wolf nicht aufgehört, sich näher ..., und die Henne hat''s nicht mal gemerkt.'::text,'heranzuschleichen'::text,'heranzuschleichen'::text,'heranschleichen'::text,'Mädel, angeblich hat der Wolf nicht aufgehört, sich näher heranzuschleichen, und die Henne hat''s nicht mal gemerkt.'::text),
(344311,38257,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вовк усе ... ближче, а курка навіть не помітила.'::text,'підкрадався'::text,'підкрадатися'::text,'підкрадатися'::text,'Подруго, кажуть, вовк усе підкрадався ближче, а курка навіть не помітила.'::text),
(344310,38257,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer el lobo siguió ... más cerca, y la gallina ni se dio cuenta.'::text,'acercándose sigilosamente'::text,'acercarse sigilosamente'::text,'se acerca sigilosamente'::text,'Amiga, al parecer el lobo siguió acercándose sigilosamente más cerca, y la gallina ni se dio cuenta.'::text),
(344309,38257,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment le loup a continué à ... de plus en plus près, et la poule n''a même rien remarqué.'::text,'s''approcher en rampant'::text,'s''approcher en rampant'::text,'s''approche en rampant'::text,'Meuf, apparemment le loup a continué à s''approcher en rampant de plus en plus près, et la poule n''a même rien remarqué.'::text),
(344312,38257,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre kurt sinsice ... devam etti ve tavuk fark etmedi bile.'::text,'yaklaşmaya'::text,'yaklaşmak'::text,'yaklaş'::text,'Kızım, duyduğuma göre kurt sinsice yaklaşmaya devam etti ve tavuk fark etmedi bile.'::text),
(344313,38257,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a farkas egyre közelebb ..., és a tyúk észre se vette.'::text,'lopakodott'::text,'lopakodni'::text,'lopakodik'::text,'Csajszi, állítólag a farkas egyre közelebb lopakodott, és a tyúk észre se vette.'::text),
(339618,37736,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Brücke ist bei der Verfolgungsjagd gebrochen, also ... die Bretter sehr alt gewesen sein.'::text,'müssen'::text,'sollten'::text,'können nicht'::text,'Die Brücke ist bei der Verfolgungsjagd gebrochen, also müssen die Bretter sehr alt gewesen sein.'::text),
(339622,37736,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Міст зламався під час погоні, тож дошки ... дуже старими.'::text,'мабуть, були'::text,'мали бути'::text,'не могли бути'::text,'Міст зламався під час погоні, тож дошки мабуть, були дуже старими.'::text),
(339621,37736,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El puente se rompió durante la persecución, así que las tablas ... muy viejas.'::text,'debían de ser'::text,'deberían haber sido'::text,'no podían ser'::text,'El puente se rompió durante la persecución, así que las tablas debían de ser muy viejas.'::text),
(339620,37736,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le pont s''est cassé pendant la course-poursuite, donc les planches ... très vieilles.'::text,'devaient être'::text,'auraient dû être'::text,'ne pouvaient pas être'::text,'Le pont s''est cassé pendant la course-poursuite, donc les planches devaient être très vieilles.'::text),
(339623,37736,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kovalamaca sırasında köprü kırıldı, yani tahtalar çok eski ...'::text,'olmalı'::text,'olmalıydı'::text,'olamaz'::text,'Kovalamaca sırasında köprü kırıldı, yani tahtalar çok eski olmalı.'::text),
(339624,37736,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A híd leszakadt az üldözés közben, szóval a deszkák nagyon régiek ...'::text,'lehettek'::text,'kellett volna, hogy legyenek'::text,'nem lehettek'::text,'A híd leszakadt az üldözés közben, szóval a deszkák nagyon régiek lehettek.'::text),
(345954,38440,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Henne hat ihre Küken die ganze Nacht ..., also war sie die ganze Nacht wach.'::text,'verteidigt'::text,'verteidigt'::text,'verteidigt'::text,'Die Henne hat ihre Küken die ganze Nacht verteidigt, also war sie die ganze Nacht wach.'::text),
(345958,38440,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Курка ... своїх курчат усю ніч, тож вона не спала всю ніч.'::text,'захищала'::text,'захищає'::text,'захищає'::text,'Курка захищала своїх курчат усю ніч, тож вона не спала всю ніч.'::text),
(345957,38440,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La gallina ... a sus pollitos toda la noche, así que ha estado despierta toda la noche.'::text,'ha estado defendiendo'::text,'está defendiendo'::text,'defiende'::text,'La gallina ha estado defendiendo a sus pollitos toda la noche, así que ha estado despierta toda la noche.'::text),
(345956,38440,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La poule ... ses poussins toute la nuit, donc elle est restée éveillée toute la nuit.'::text,'a défendu'::text,'défend'::text,'défend'::text,'La poule a défendu ses poussins toute la nuit, donc elle est restée éveillée toute la nuit.'::text),
(345959,38440,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tavuk bütün gece civcivlerini ..., yani bütün gece uyanık kaldı.'::text,'korudu'::text,'koruyor'::text,'korur'::text,'Tavuk bütün gece civcivlerini korudu, yani bütün gece uyanık kaldı.'::text),
(345960,38440,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tyúk egész éjjel ... a csibéit, szóval egész éjjel ébren volt.'::text,'védte'::text,'védi'::text,'védi'::text,'A tyúk egész éjjel védte a csibéit, szóval egész éjjel ébren volt.'::text),
(345990,38444,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Henne, ... Küken zweimal in Gefahr waren, verteidigte sie wie ein echter Profi.'::text,'deren'::text,'die'::text,'welche'::text,'Die Henne, deren Küken zweimal in Gefahr waren, verteidigte sie wie ein echter Profi.'::text),
(345994,38444,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Курка, ... курчата двічі були в небезпеці, захистила їх як справжній профі.'::text,'чиї'::text,'яка'::text,'котра'::text,'Курка, чиї курчата двічі були в небезпеці, захистила їх як справжній профі.'::text),
(345993,38444,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La gallina, ... pollitos estuvieron en peligro dos veces, los defendió como una auténtica profesional.'::text,'cuyos'::text,'que'::text,'la cual'::text,'La gallina, cuyos pollitos estuvieron en peligro dos veces, los defendió como una auténtica profesional.'::text),
(345992,38444,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La poule, ... les poussins ont été en danger deux fois, les a défendus comme une vraie pro.'::text,'dont'::text,'qui'::text,'laquelle'::text,'La poule, dont les poussins ont été en danger deux fois, les a défendus comme une vraie pro.'::text),
(345995,38444,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tavuk, ... civcivleri iki kez tehlikeye girdi, onları gerçek bir profesyonel gibi korudu.'::text,'ki'::text,'kim'::text,'hangi'::text,'Tavuk, ki civcivleri iki kez tehlikeye girdi, onları gerçek bir profesyonel gibi korudu.'::text),
(345996,38444,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tyúk, ... csibéi kétszer is veszélybe kerültek, igazi profiként védte meg őket.'::text,'akinek a'::text,'aki'::text,'amely'::text,'A tyúk, akinek a csibéi kétszer is veszélybe kerültek, igazi profiként védte meg őket.'::text),
(388911,43213,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, morgen um diese Zeit ... sich diese Henne wieder an den Wölfen vorbei, kein Witz.'::text,'schleicht'::text,'schleicht'::text,'schleicht'::text,'Bro, morgen um diese Zeit schleicht sich diese Henne wieder an den Wölfen vorbei, kein Witz.'::text),
(388915,43213,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, завтра в цей час та курка знову ... повз вовків, без жартів.'::text,'прокрадатиметься'::text,'прокрадеться'::text,'прокрадається'::text,'Бро, завтра в цей час та курка знову прокрадатиметься повз вовків, без жартів.'::text),
(388914,43213,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, mañana a esta hora esa gallina ... otra vez a escondidas junto a los lobos, en serio.'::text,'estará pasando'::text,'pasará'::text,'pasa'::text,'Bro, mañana a esta hora esa gallina estará pasando otra vez a escondidas junto a los lobos, en serio.'::text),
(388913,43213,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, demain à cette heure-ci, cette poule ... encore devant les loups, sans mentir.'::text,'sera en train de se faufiler'::text,'se faufilera'::text,'se faufile'::text,'Frérot, demain à cette heure-ci, cette poule sera en train de se faufiler encore devant les loups, sans mentir.'::text),
(388916,43213,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, yarın bu saatte o tavuk yine kurtların yanından sinsice ..., yemin ederim.'::text,'geçiyor olacak'::text,'geçecek'::text,'geçer'::text,'Kanka, yarın bu saatte o tavuk yine kurtların yanından sinsice geçiyor olacak, yemin ederim.'::text),
(388917,43213,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, holnap ilyenkor az a tyúk megint ... a farkasok mellett, komolyan.'::text,'fog elosonni'::text,'elosonik'::text,'elosonik'::text,'Tesó, holnap ilyenkor az a tyúk megint fog elosonni a farkasok mellett, komolyan.'::text),
(358302,39812,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein winziges Glühwürmchen leuchtet natürlich so hell wie eine Lampe, ...?'::text,'oder'::text,'nicht wahr'::text,'oder'::text,'Ein winziges Glühwürmchen leuchtet natürlich so hell wie eine Lampe, oder?'::text),
(358306,39812,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Один крихітний світлячок, звісно, світить яскраво, як лампа, ...?'::text,'так'::text,'так'::text,'так'::text,'Один крихітний світлячок, звісно, світить яскраво, як лампа, так?'::text),
(358305,39812,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una luciérnaga diminuta obviamente brilla tanto como una lámpara, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Una luciérnaga diminuta obviamente brilla tanto como una lámpara, ¿verdad?'::text),
(358304,39812,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une minuscule luciole brille évidemment aussi fort qu''une lampe, ... ?'::text,'non'::text,'non'::text,'non'::text,'Une minuscule luciole brille évidemment aussi fort qu''une lampe, non ?'::text),
(358307,39812,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minicik bir ateş böceği tabii ki bir lamba kadar parlak ışıldar, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Minicik bir ateş böceği tabii ki bir lamba kadar parlak ışıldar, değil mi?'::text),
(358308,39812,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy apró szentjánosbogár nyilván olyan fényesen világít, mint egy lámpa, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'Egy apró szentjánosbogár nyilván olyan fényesen világít, mint egy lámpa, ugye?'::text),
(358374,39820,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Glühwürmchen, ... Leuchten das Gesicht des Kükens erhellt, sitzt in einem Glas.'::text,'dessen'::text,'das'::text,'der'::text,'Das Glühwürmchen, dessen Leuchten das Gesicht des Kükens erhellt, sitzt in einem Glas.'::text),
(358378,39820,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Світлячок, ... сяйво освітлює мордочку курчати, сидить у скляній банці.'::text,'чиє'::text,'який'::text,'хто'::text,'Світлячок, чиє сяйво освітлює мордочку курчати, сидить у скляній банці.'::text),
(358377,39820,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La luciérnaga, ... brillo ilumina la cara del pollito, está dentro de un tarro de cristal.'::text,'cuyo'::text,'que'::text,'quien'::text,'La luciérnaga, cuyo brillo ilumina la cara del pollito, está dentro de un tarro de cristal.'::text),
(358376,39820,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La luciole, ... la lueur éclaire le visage du poussin, est dans un bocal en verre.'::text,'dont'::text,'que'::text,'qui'::text,'La luciole, dont la lueur éclaire le visage du poussin, est dans un bocal en verre.'::text),
(358379,39820,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ateş böceği, ... ışığı civcivin yüzünü aydınlatıyor, cam bir kavanozun içinde duruyor.'::text,'ki'::text,'hangi'::text,'kim'::text,'Ateş böceği, ki ışığı civcivin yüzünü aydınlatıyor, cam bir kavanozun içinde duruyor.'::text),
(358380,39820,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szentjánosbogár, ... fénye megvilágítja a csibe arcát, egy üvegben ül.'::text,'amelynek a'::text,'amely'::text,'aki'::text,'A szentjánosbogár, amelynek a fénye megvilágítja a csibe arcát, egy üvegben ül.'::text),
(357987,39777,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mais ... von einer großzügigen Henne ins Loch geschoben. Die Mäuse haben natürlich die ganze Arbeit gemacht.'::text,'wurde'::text,'schob'::text,'wird'::text,'Der Mais wurde von einer großzügigen Henne ins Loch geschoben. Die Mäuse haben natürlich die ganze Arbeit gemacht.'::text),
(357991,39777,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кукурудза ... в нору однією щедрою куркою. Миші, звісно, зробили всю роботу.'::text,'була заштовхана'::text,'заштовхала'::text,'заштовхується'::text,'Кукурудза була заштовхана в нору однією щедрою куркою. Миші, звісно, зробили всю роботу.'::text),
(357990,39777,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El maíz ... al agujero por una gallina generosa. Claramente los ratones hicieron todo el trabajo.'::text,'fue empujado'::text,'empujó'::text,'es empujado'::text,'El maíz fue empujado al agujero por una gallina generosa. Claramente los ratones hicieron todo el trabajo.'::text),
(357989,39777,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le maïs ... dans le trou par une poule généreuse. Les souris ont clairement fait tout le travail.'::text,'a été poussé'::text,'a poussé'::text,'est poussé'::text,'Le maïs a été poussé dans le trou par une poule généreuse. Les souris ont clairement fait tout le travail.'::text),
(357992,39777,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mısır, cömert bir tavuk tarafından deliğe ..., belli ki bütün işi fareler yaptı.'::text,'itildi'::text,'itti'::text,'itiliyor'::text,'Mısır, cömert bir tavuk tarafından deliğe itildi, belli ki bütün işi fareler yaptı.'::text),
(357993,39777,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kukorica egy nagylelkű tyúk által ... a lyukba. Nyilván az egerek végezték az összes munkát.'::text,'lett betolva'::text,'betolt'::text,'be van tolva'::text,'A kukorica egy nagylelkű tyúk által lett betolva a lyukba. Nyilván az egerek végezték az összes munkát.'::text),
(369174,41020,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Anfangs ... das Individuum den Welpen täglich aus, bevor es den Alligator für ihn hielt.'::text,'führte'::text,'führte'::text,'war gewohnt zu führen'::text,'Anfangs führte das Individuum den Welpen täglich aus, bevor es den Alligator für ihn hielt.'::text),
(369178,41020,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Спочатку особина ... вигулювала цуценя щодня, перш ніж сплутала з ним алігатора.'::text,'зазвичай'::text,'зазвичай'::text,'звикла'::text,'Спочатку особина зазвичай вигулювала цуценя щодня, перш ніж сплутала з ним алігатора.'::text),
(369177,41020,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Inicialmente, el individuo ... pasear al cachorro a diario, antes de confundir al caimán con él.'::text,'solía'::text,'solía'::text,'estaba acostumbrado a'::text,'Inicialmente, el individuo solía pasear al cachorro a diario, antes de confundir al caimán con él.'::text),
(369176,41020,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au départ, l''individu ... le chiot tous les jours, avant de le confondre avec l''alligator.'::text,'promenait'::text,'promenait'::text,'avait l''habitude de promener'::text,'Au départ, l''individu promenait le chiot tous les jours, avant de le confondre avec l''alligator.'::text),
(369179,41020,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Başlangıçta birey, timsahı onunla karıştırmadan önce köpek yavrusunu her gün ...'::text,'gezdirirdi'::text,'gezdirirdi'::text,'gezdirmeye alışkındı'::text,'Başlangıçta birey, timsahı onunla karıştırmadan önce köpek yavrusunu her gün gezdirirdi.'::text),
(369180,41020,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kezdetben az egyed naponta ... a kiskutyát, mielőtt összetévesztette vele az aligátort.'::text,'sétáltatta'::text,'sétáltatta'::text,'hozzá volt szokva sétáltatni'::text,'Kezdetben az egyed naponta sétáltatta a kiskutyát, mielőtt összetévesztette vele az aligátort.'::text),
(369201,41023,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als er sie aufhielt, ... sie den Alligator schon für ihren Hund gehalten. Ein absoluter Albtraum!'::text,'hatte'::text,'hat'::text,'hält'::text,'Als er sie aufhielt, hatte sie den Alligator schon für ihren Hund gehalten. Ein absoluter Albtraum!'::text),
(369205,41023,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли він її зупинив, вона вже ... того алігатора зі своїм собакою. Абсолютний жах!'::text,'сплутала'::text,'сплутала'::text,'плутає'::text,'Коли він її зупинив, вона вже сплутала того алігатора зі своїм собакою. Абсолютний жах!'::text),
(369204,41023,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando él la detuvo, ella ya ... a ese caimán con su perro. ¡Una pesadilla absoluta!'::text,'había confundido'::text,'ha confundido'::text,'confunde'::text,'Cuando él la detuvo, ella ya había confundido a ese caimán con su perro. ¡Una pesadilla absoluta!'::text),
(369203,41023,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand il l''a arrêtée, elle ... déjà cet alligator pour son chien. Un vrai cauchemar !'::text,'avait pris'::text,'a pris'::text,'prend'::text,'Quand il l''a arrêtée, elle avait pris déjà cet alligator pour son chien. Un vrai cauchemar !'::text),
(369206,41023,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O onu durdurduğunda, o çoktan o timsahı köpeğiyle ..., tam bir kâbus!'::text,'karıştırmıştı'::text,'karıştırdı'::text,'karıştırıyor'::text,'O onu durdurduğunda, o çoktan o timsahı köpeğiyle karıştırmıştı, tam bir kâbus!'::text),
(369207,41023,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire megállította, ő már ... azt az aligátort a kutyájával. Abszolút rémálom!'::text,'összetévesztette'::text,'összetévesztette'::text,'összetéveszti'::text,'Mire megállította, ő már összetévesztette azt az aligátort a kutyájával. Abszolút rémálom!'::text),
(376581,41843,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Becher über 300 Gramm wiegt, ... er laut Bericht eine gehäkelte Maus platt.'::text,'drückt'::text,'drückte'::text,'wird drücken'::text,'Wenn ein Becher über 300 Gramm wiegt, drückt er laut Bericht eine gehäkelte Maus platt.'::text),
(376585,41843,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо кухоль важить понад 300 грамів, він ... в''язану гачком мишку, згідно зі звітом.'::text,'розплющує'::text,'розплющив'::text,'розплющить'::text,'Якщо кухоль важить понад 300 грамів, він розплющує в''язану гачком мишку, згідно зі звітом.'::text),
(376584,41843,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si una taza pesa más de 300 gramos, esa taza ... un ratón de ganchillo, según el informe.'::text,'aplasta'::text,'aplastó'::text,'aplastará'::text,'Si una taza pesa más de 300 gramos, esa taza aplasta un ratón de ganchillo, según el informe.'::text),
(376583,41843,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un mug pèse plus de 300 grammes, il ... une souris au crochet, selon le rapport.'::text,'aplatit'::text,'aplatissait'::text,'aplatira'::text,'Si un mug pèse plus de 300 grammes, il aplatit une souris au crochet, selon le rapport.'::text),
(376586,41843,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rapora göre bir kupa 300 gramın üzerindeyse, o, tığ işi bir fareyi ...'::text,'yassılaştırır'::text,'yassılaştırdı'::text,'yassılaştıracak'::text,'Rapora göre bir kupa 300 gramın üzerindeyse, o, tığ işi bir fareyi yassılaştırır.'::text),
(376587,41843,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy bögre 300 grammnál nehezebb, az a bögre ... a horgolt egeret, a jelentés szerint.'::text,'laposra nyomja'::text,'laposra nyomta'::text,'laposra fogja nyomni'::text,'Ha egy bögre 300 grammnál nehezebb, az a bögre laposra nyomja a horgolt egeret, a jelentés szerint.'::text),
(388218,43136,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieser Hang ist echt steil, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Dieser Hang ist echt steil, oder?'::text),
(388222,43136,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цей схил дуже крутий, ...?'::text,'так'::text,'так'::text,'так'::text,'Цей схил дуже крутий, так?'::text),
(388221,43136,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esta pendiente es muy empinada, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Esta pendiente es muy empinada, ¿verdad?'::text),
(388220,43136,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cette pente est très raide, ... ?'::text,'non'::text,'non'::text,'non'::text,'Cette pente est très raide, non ?'::text),
(388223,43136,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu yamaç çok dik, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Bu yamaç çok dik, değil mi?'::text),
(388224,43136,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a lejtő nagyon meredek, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'Ez a lejtő nagyon meredek, ugye?'::text),
(388245,43139,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Sonnenuntergang ... er den ganzen Hang runter. Offensichtlich nur ein kleiner Morgenspaziergang.'::text,'fährt'::text,'fährt'::text,'fährt gerade'::text,'Bis zum Sonnenuntergang fährt er den ganzen Hang runter. Offensichtlich nur ein kleiner Morgenspaziergang.'::text),
(388249,43139,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До заходу сонця він ... весь схил. Очевидно, просто невеличка ранкова прогулянка.'::text,'з''їде'::text,'з''їде'::text,'з''їжджатиме'::text,'До заходу сонця він з''їде весь схил. Очевидно, просто невеличка ранкова прогулянка.'::text),
(388248,43139,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el atardecer, él ... toda la pendiente. Obviamente, solo un paseíto matutino.'::text,'habrá esquiado'::text,'esquiará'::text,'estará esquiando'::text,'Para el atardecer, él habrá esquiado toda la pendiente. Obviamente, solo un paseíto matutino.'::text),
(388247,43139,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le coucher du soleil, il ... toute la pente. Évidemment, juste une petite balade matinale.'::text,'aura descendu'::text,'descendra'::text,'sera en train de descendre'::text,'D''ici le coucher du soleil, il aura descendu toute la pente. Évidemment, juste une petite balade matinale.'::text),
(388250,43139,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımına kadar o bütün yamacı kayarak ..., belli ki küçük bir sabah yürüyüşü.'::text,'inmiş olacak'::text,'inecek'::text,'iniyor olacak'::text,'Gün batımına kadar o bütün yamacı kayarak inmiş olacak, belli ki küçük bir sabah yürüyüşü.'::text),
(388251,43139,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Naplementéig ő ... az egész lejtőt. Nyilván csak egy kis reggeli séta.'::text,'lesíeli'::text,'le fogja síelni'::text,'síelni fog'::text,'Naplementéig ő lesíeli az egész lejtőt. Nyilván csak egy kis reggeli séta.'::text),
(353559,39285,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Adler, ... direkt vor der Kamera gefischt hat, wollte eindeutig berühmt werden.'::text,'der'::text,'was'::text,'dessen'::text,'Der Adler, der direkt vor der Kamera gefischt hat, wollte eindeutig berühmt werden.'::text),
(353563,39285,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Орел, ... рибалив просто перед камерою, явно хотів прославитися.'::text,'який'::text,'що'::text,'чий'::text,'Орел, який рибалив просто перед камерою, явно хотів прославитися.'::text),
(353562,39285,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El águila ... pescó justo delante de la cámara claramente quería ser famosa.'::text,'que'::text,'lo que'::text,'cuya'::text,'El águila que pescó justo delante de la cámara claramente quería ser famosa.'::text),
(353561,39285,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''aigle ... a pêché juste devant la caméra voulait clairement devenir célèbre.'::text,'qui'::text,'ce qui'::text,'dont'::text,'L''aigle qui a pêché juste devant la caméra voulait clairement devenir célèbre.'::text),
(353564,39285,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kameranın tam önünde balık ... kartal belli ki ünlü olmak istiyordu.'::text,'tutan'::text,'ne'::text,'kimin'::text,'Kameranın tam önünde balık tutan kartal belli ki ünlü olmak istiyordu.'::text),
(353565,39285,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sas, ... közvetlenül a kamera előtt halászott, egyértelműen híres akart lenni.'::text,'amely'::text,'ami'::text,'amelynek'::text,'A sas, amely közvetlenül a kamera előtt halászott, egyértelműen híres akart lenni.'::text),
(353604,39290,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Adler ... jahrelang in dieser Bucht gefischt, bevor ihn jemand gefilmt hat.'::text,'hatte'::text,'hat'::text,'hat'::text,'Der Adler hatte jahrelang in dieser Bucht gefischt, bevor ihn jemand gefilmt hat.'::text),
(353608,39290,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Орел ... в цій затоці роками, перш ніж хтось його зняв.'::text,'рибалив'::text,'рибалив'::text,'рибалив'::text,'Орел рибалив в цій затоці роками, перш ніж хтось його зняв.'::text),
(353607,39290,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El águila ... en esta bahía durante años antes de que alguien la grabara.'::text,'había estado pescando'::text,'ha estado pescando'::text,'ha pescado'::text,'El águila había estado pescando en esta bahía durante años antes de que alguien la grabara.'::text),
(353606,39290,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''aigle ... dans cette baie depuis des années quand quelqu''un l''a filmé.'::text,'pêchait'::text,'pêche'::text,'a pêché'::text,'L''aigle pêchait dans cette baie depuis des années quand quelqu''un l''a filmé.'::text),
(353609,39290,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biri onu çekmeden önce kartal yıllarca bu koyda balık ...'::text,'avlıyordu'::text,'avlıyor'::text,'avladı'::text,'Biri onu çekmeden önce kartal yıllarca bu koyda balık avlıyordu.'::text),
(353610,39290,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sas évek óta ... ebben az öbölben, mielőtt bárki lefilmezte volna.'::text,'halászott'::text,'halászik'::text,'halászott'::text,'A sas évek óta halászott ebben az öbölben, mielőtt bárki lefilmezte volna.'::text),
(399549,44395,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ich wünschte, ich ... so eine Tiefgarage, echt jetzt.'::text,'hätte'::text,'habe'::text,'würde haben'::text,'Bro, ich wünschte, ich hätte so eine Tiefgarage, echt jetzt.'::text),
(399553,44395,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, от би я ... такий підземний гараж, чесно.'::text,'мав'::text,'маю'::text,'мав би'::text,'Бро, от би я мав такий підземний гараж, чесно.'::text),
(399552,44395,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ojalá yo ... un garaje subterráneo así, en serio.'::text,'tuviera'::text,'tengo'::text,'tendría'::text,'Bro, ojalá yo tuviera un garaje subterráneo así, en serio.'::text),
(399551,44395,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, si seulement j''... un garage souterrain comme ça, sérieux.'::text,'avais'::text,'ai'::text,'aurais'::text,'Frérot, si seulement j''avais un garage souterrain comme ça, sérieux.'::text),
(399554,44395,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, keşke ben de böyle bir yeraltı garajına ..., cidden.'::text,'sahip olsam'::text,'sahibim'::text,'sahip olurdum'::text,'Kanka, keşke ben de böyle bir yeraltı garajına sahip olsam, cidden.'::text),
(399555,44395,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, bárcsak nekem is ... egy ilyen mélygarázsom, komolyan.'::text,'lenne'::text,'van'::text,'lenne'::text,'Tesó, bárcsak nekem is lenne egy ilyen mélygarázsom, komolyan.'::text),
(349194,38800,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Paraglider seine Füße zu tief durchzieht, ... der See ihn komplett rein!'::text,'zieht'::text,'zog'::text,'würde ziehen'::text,'Wenn ein Paraglider seine Füße zu tief durchzieht, zieht der See ihn komplett rein!'::text),
(349198,38800,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо парапланерист занурює ноги надто глибоко, озеро ... його повністю!'::text,'затягує'::text,'затягнуло'::text,'затягнуло б'::text,'Якщо парапланерист занурює ноги надто глибоко, озеро затягує його повністю!'::text),
(349197,38800,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si un parapentista arrastra los pies demasiado hondo, el lago lo ... por completo!'::text,'traga'::text,'tragó'::text,'tragaría'::text,'¡Si un parapentista arrastra los pies demasiado hondo, el lago lo traga por completo!'::text),
(349196,38800,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un parapentiste traîne les pieds trop profond, le lac ... complètement !'::text,'l''aspire'::text,'l''a aspiré'::text,'l''aspirerait'::text,'Si un parapentiste traîne les pieds trop profond, le lac l''aspire complètement !'::text),
(349199,38800,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir yamaç paraşütçüsü ayaklarını çok derine sürterse, göl onu tamamen içine ...!'::text,'çeker'::text,'çekti'::text,'çekerdi'::text,'Bir yamaç paraşütçüsü ayaklarını çok derine sürterse, göl onu tamamen içine çeker!'::text),
(349200,38800,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy siklóernyős túl mélyen húzza a lábát, a tó teljesen ... őt!'::text,'beszippantja'::text,'beszippantotta'::text,'beszippantaná'::text,'Ha egy siklóernyős túl mélyen húzza a lábát, a tó teljesen beszippantja őt!'::text),
(349266,38808,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wünscht sich wahrscheinlich, er ... seine Schuhe durch den See gezogen. Nasse Socken, makellos.'::text,'hätte nicht'::text,'zog nicht'::text,'würde nicht'::text,'Er wünscht sich wahrscheinlich, er hätte nicht seine Schuhe durch den See gezogen. Nasse Socken, makellos.'::text),
(349270,38808,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він, мабуть, хотів би, щоб ... черевики по озеру. Мокрі шкарпетки, бездоганно.'::text,'не тягнув'::text,'не тягнув'::text,'не тягнув'::text,'Він, мабуть, хотів би, щоб не тягнув черевики по озеру. Мокрі шкарпетки, бездоганно.'::text),
(349269,38808,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seguramente él desearía no ... las botas por el lago. Calcetines mojados, impecable.'::text,'haber arrastrado'::text,'arrastrar'::text,'arrastrar'::text,'Seguramente él desearía no haber arrastrado las botas por el lago. Calcetines mojados, impecable.'::text),
(349268,38808,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il aimerait sûrement ne pas ... ses bottes dans le lac. Chaussettes mouillées, parfait.'::text,'avoir traîné'::text,'traîner'::text,'traîner'::text,'Il aimerait sûrement ne pas avoir traîné ses bottes dans le lac. Chaussettes mouillées, parfait.'::text),
(349271,38808,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O muhtemelen botlarını gölde ... diliyordur. Islak çoraplar, kusursuz.'::text,'sürüklememiş olmayı'::text,'sürüklememeyi'::text,'sürüklemeyecek olmayı'::text,'O muhtemelen botlarını gölde sürüklememiş olmayı diliyordur. Islak çoraplar, kusursuz.'::text),
(349272,38808,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő valószínűleg azt kívánja, bárcsak ne ... végig a bakancsát a tavon. Vizes zokni, hibátlan.'::text,'húzta volna'::text,'húzná'::text,'húzná'::text,'Ő valószínűleg azt kívánja, bárcsak ne húzta volna végig a bakancsát a tavon. Vizes zokni, hibátlan.'::text),
(358428,39826,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, du kannst nicht aufhören, den goldenen Sonnenuntergang über der Bucht anzuschauen, und ...'::text,'der Schwimmer auch nicht'::text,'der Schwimmer auch'::text,'der Schwimmer auch nicht'::text,'Ehrlich gesagt, du kannst nicht aufhören, den goldenen Sonnenuntergang über der Bucht anzuschauen, und der Schwimmer auch nicht.'::text),
(358432,39826,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти не можеш відірватися від золотого заходу сонця над затокою, і ...'::text,'плавець теж не може'::text,'плавець теж може'::text,'плавець теж ні'::text,'Чесно, ти не можеш відірватися від золотого заходу сонця над затокою, і плавець теж не може.'::text),
(358431,39826,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, tú no puedes dejar de mirar la puesta de sol dorada sobre la bahía, y ...'::text,'el nadador tampoco'::text,'el nadador también'::text,'el nadador tampoco'::text,'No te voy a mentir, tú no puedes dejar de mirar la puesta de sol dorada sobre la bahía, y el nadador tampoco.'::text),
(358430,39826,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sans mentir, tu n''arrives pas à arrêter de regarder le coucher de soleil doré sur la baie, et ...'::text,'le nageur non plus'::text,'le nageur aussi'::text,'le nageur non plus'::text,'Sans mentir, tu n''arrives pas à arrêter de regarder le coucher de soleil doré sur la baie, et le nageur non plus.'::text),
(358433,39826,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, sen körfezin üzerindeki altın rengi gün batımını izlemeyi bırakamıyorsun, ve ...'::text,'yüzücü de bırakamıyor'::text,'yüzücü de bırakabiliyor'::text,'yüzücü de bırakmıyor'::text,'Yalan yok, sen körfezin üzerindeki altın rengi gün batımını izlemeyi bırakamıyorsun, ve yüzücü de bırakamıyor.'::text),
(358434,39826,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem kamu, te nem tudod abbahagyni az öböl feletti arany naplemente nézését, és ...'::text,'az úszó sem'::text,'az úszó is'::text,'az úszó sem'::text,'Nem kamu, te nem tudod abbahagyni az öböl feletti arany naplemente nézését, és az úszó sem.'::text),
(358437,39827,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Drohne ... schon minutenlang über den Klippen, bevor das Meer golden wurde.'::text,'flog'::text,'fliegt'::text,'flog'::text,'Die Drohne flog schon minutenlang über den Klippen, bevor das Meer golden wurde.'::text),
(358441,39827,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дрон ... над скелями кілька хвилин, перш ніж море стало золотим.'::text,'літав'::text,'літає'::text,'летів'::text,'Дрон літав над скелями кілька хвилин, перш ніж море стало золотим.'::text),
(358440,39827,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El dron ... sobre los acantilados durante minutos antes de que el mar se volviera dorado.'::text,'había estado volando'::text,'ha estado volando'::text,'estaba volando'::text,'El dron había estado volando sobre los acantilados durante minutos antes de que el mar se volviera dorado.'::text),
(358439,39827,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le drone ... au-dessus des falaises depuis des minutes quand la mer est devenue dorée.'::text,'volait'::text,'vole'::text,'volait'::text,'Le drone volait au-dessus des falaises depuis des minutes quand la mer est devenue dorée.'::text),
(358442,39827,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deniz altın rengine dönmeden önce drone dakikalarca uçurumların üzerinde ...'::text,'uçuyordu'::text,'uçuyor'::text,'uçuyordu'::text,'Deniz altın rengine dönmeden önce drone dakikalarca uçurumların üzerinde uçuyordu.'::text),
(358443,39827,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A drón percek óta ... a sziklák fölött, mielőtt a tenger arany színűvé vált.'::text,'repült'::text,'repül'::text,'repült'::text,'A drón percek óta repült a sziklák fölött, mielőtt a tenger arany színűvé vált.'::text),
(399891,44433,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie die Bikes noch länger aufrecht halten, ... das in einer totalen Katastrophe!'::text,'endet'::text,'würde enden'::text,'endete'::text,'Wenn sie die Bikes noch länger aufrecht halten, endet das in einer totalen Katastrophe!'::text),
(399895,44433,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вони триматимуть мотоцикли вертикально ще довше, це ... повною катастрофою!'::text,'закінчиться'::text,'закінчилося б'::text,'закінчилося'::text,'Якщо вони триматимуть мотоцикли вертикально ще довше, це закінчиться повною катастрофою!'::text),
(399894,44433,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si ellos mantienen las motos levantadas más tiempo, esto ... en un desastre total!'::text,'acabará'::text,'acabaría'::text,'acabó'::text,'¡Si ellos mantienen las motos levantadas más tiempo, esto acabará en un desastre total!'::text),
(399893,44433,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''ils gardent les motos cabrées plus longtemps, ça ... en catastrophe totale !'::text,'finira'::text,'finirait'::text,'a fini'::text,'S''ils gardent les motos cabrées plus longtemps, ça finira en catastrophe totale !'::text),
(399896,44433,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar motosikletleri daha uzun süre dik tutarsa, bu tam bir felaketle ...!'::text,'bitecek'::text,'biterdi'::text,'bitti'::text,'Onlar motosikletleri daha uzun süre dik tutarsa, bu tam bir felaketle bitecek!'::text),
(399897,44433,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ők még tovább tartják függőlegesen a motorokat, az totális katasztrófával ...!'::text,'végződik'::text,'végződne'::text,'végződött'::text,'Ha ők még tovább tartják függőlegesen a motorokat, az totális katasztrófával végződik!'::text),
(399936,44438,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, bis zum Sonnenuntergang wirst du das Bike einen ganzen Kilometer aufrecht ...'::text,'gefahren haben'::text,'fahren'::text,'fährst'::text,'Ehrlich gesagt, bis zum Sonnenuntergang wirst du das Bike einen ganzen Kilometer aufrecht gefahren haben.'::text),
(399940,44438,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, до заходу сонця ти ... на тому мотоциклі вертикально цілий кілометр.'::text,'проїдеш'::text,'проїдеш'::text,'їдеш'::text,'Чесно, до заходу сонця ти проїдеш на тому мотоциклі вертикально цілий кілометр.'::text),
(399939,44438,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, para el atardecer tú ... esa moto levantada un kilómetro entero.'::text,'habrás llevado'::text,'llevarás'::text,'llevas'::text,'No te voy a mentir, para el atardecer tú habrás llevado esa moto levantada un kilómetro entero.'::text),
(399938,44438,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sans mentir, d''ici le coucher du soleil, tu ... cette moto cabrée sur un kilomètre entier.'::text,'auras conduit'::text,'conduiras'::text,'conduis'::text,'Sans mentir, d''ici le coucher du soleil, tu auras conduit cette moto cabrée sur un kilomètre entier.'::text),
(399941,44438,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, gün batımına kadar sen o motoru tam bir kilometre dik şekilde ...'::text,'sürmüş olacaksın'::text,'süreceksin'::text,'sürüyorsun'::text,'Yalan yok, gün batımına kadar sen o motoru tam bir kilometre dik şekilde sürmüş olacaksın.'::text),
(399942,44438,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem kamu, naplementéig te egy teljes kilométert ... azzal a motorral függőlegesen.'::text,'megteszel'::text,'fogsz menni'::text,'mész'::text,'Nem kamu, naplementéig te egy teljes kilométert megteszel azzal a motorral függőlegesen.'::text),
(380226,42248,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, der Hai, ... er gerettet hat, ist angeblich am nächsten Tag zurückgekommen.'::text,'den'::text,'wer'::text,'dessen'::text,'Hör mal, der Hai, den er gerettet hat, ist angeblich am nächsten Tag zurückgekommen.'::text),
(380230,42248,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, акула, ... він урятував, кажуть, повернулася наступного дня.'::text,'яку'::text,'хто'::text,'чия'::text,'Слухай, акула, яку він урятував, кажуть, повернулася наступного дня.'::text),
(380229,42248,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, el tiburón ... él rescató al parecer volvió al día siguiente.'::text,'que'::text,'quien'::text,'cuyo'::text,'Oye, el tiburón que él rescató al parecer volvió al día siguiente.'::text),
(380228,42248,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, le requin ... a été sauvé par lui est apparemment revenu le lendemain.'::text,'qui'::text,'que'::text,'dont'::text,'Écoute, le requin qui a été sauvé par lui est apparemment revenu le lendemain.'::text),
(380231,42248,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duyduğuma göre onun ... köpekbalığı ertesi gün geri gelmiş.'::text,'kurtardığı'::text,'kim'::text,'kimin'::text,'Dinle, duyduğuma göre onun kurtardığı köpekbalığı ertesi gün geri gelmiş.'::text),
(380232,42248,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, a cápa, ... ő megmentett, állítólag másnap visszajött.'::text,'amelyet'::text,'aki'::text,'amelynek'::text,'Figyelj, a cápa, amelyet ő megmentett, állítólag másnap visszajött.'::text),
(380280,42254,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... den Hai schon gerettet, als die nächste Welle kam.'::text,'hatte'::text,'hat'::text,'rettet'::text,'Er hatte den Hai schon gerettet, als die nächste Welle kam.'::text),
(380284,42254,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... акулу ще до того, як прийшла наступна хвиля.'::text,'урятував'::text,'урятував'::text,'рятує'::text,'Він урятував акулу ще до того, як прийшла наступна хвиля.'::text),
(380283,42254,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ya ... al tiburón cuando llegó la siguiente ola.'::text,'había rescatado'::text,'ha rescatado'::text,'rescata'::text,'Él ya había rescatado al tiburón cuando llegó la siguiente ola.'::text),
(380282,42254,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... le requin quand la vague suivante est arrivée.'::text,'avait déjà sauvé'::text,'a déjà sauvé'::text,'sauve'::text,'Il avait déjà sauvé le requin quand la vague suivante est arrivée.'::text),
(380285,42254,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir sonraki dalga geldiğinde o, köpekbalığını çoktan ...'::text,'kurtarmıştı'::text,'kurtardı'::text,'kurtarıyor'::text,'Bir sonraki dalga geldiğinde o, köpekbalığını çoktan kurtarmıştı.'::text),
(380286,42254,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire megjött a következő hullám, ő már ... a cápát.'::text,'megmentette'::text,'megmentette'::text,'menti'::text,'Mire megjött a következő hullám, ő már megmentette a cápát.'::text),
(332913,36991,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hamster ... seinen Ausweis, als er einschlief, weil der Ausweis um seinen Hals hing.'::text,'trug'::text,'trug'::text,'hat getragen'::text,'Der Hamster trug seinen Ausweis, als er einschlief, weil der Ausweis um seinen Hals hing.'::text),
(332917,36991,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хом''як ... свій бейдж, коли заснув, бо бейдж був у нього на шиї.'::text,'носив'::text,'носив'::text,'носив'::text,'Хом''як носив свій бейдж, коли заснув, бо бейдж був у нього на шиї.'::text),
(332916,36991,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hámster ... su credencial cuando se quedó dormido, porque la credencial estaba alrededor de su cuello.'::text,'llevaba puesta'::text,'llevó puesta'::text,'ha llevado puesta'::text,'El hámster llevaba puesta su credencial cuando se quedó dormido, porque la credencial estaba alrededor de su cuello.'::text),
(332915,36991,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le hamster ... son badge quand il s''est endormi, parce que le badge était autour de son cou.'::text,'portait'::text,'a porté'::text,'a porté'::text,'Le hamster portait son badge quand il s''est endormi, parce que le badge était autour de son cou.'::text),
(332918,36991,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hamster uyuyakaldığında kartını ..., çünkü kart boynundaydı.'::text,'takıyordu'::text,'taktı'::text,'takmıştır'::text,'Hamster uyuyakaldığında kartını takıyordu, çünkü kart boynundaydı.'::text),
(332919,36991,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hörcsög ... a belépőkártyáját, amikor elaludt, mert a kártya a nyakában volt.'::text,'viselte'::text,'viselte'::text,'viselte'::text,'A hörcsög viselte a belépőkártyáját, amikor elaludt, mert a kártya a nyakában volt.'::text),
(332976,36998,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hamster, ... Ausweis die Bürotür öffnet, geht um fünf Uhr.'::text,'dessen'::text,'der'::text,'wer'::text,'Der Hamster, dessen Ausweis die Bürotür öffnet, geht um fünf Uhr.'::text),
