(350521,38947,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Насправді ..., який видає цей двигун, свідчить про велике навантаження.'::text,'чорний дим'::text,'чорний дим'::text,'чорні дими'::text,'Насправді чорний дим, який видає цей двигун, свідчить про велике навантаження.'::text),
